export default {"f-card-c6a-teach":{"kind":"lesson","src":"card:c6a#teach","level":6,"topics":["card:c6a","ch:c6","who:nana"],"title":"Interest, both ways","body":"Interest is rent on money. Save, and the bank pays you rent. Borrow, and you pay rent. Which side you're on makes the difference.","route":"#/atlas/c6a","cta":"Open the lesson","maths":"M10","card":"c6a","source":"Chapter 6 · Borrowing · with Nana Bizz","id":"f-card-c6a-teach","bands":["sprout","builder"],"grp":"card:c6a"},"f-card-c6a-eg":{"kind":"example","src":"card:c6a#eg","level":6,"topics":["card:c6a","ch:c6","who:nana"],"title":"Interest, both ways","body":"Borrowing isn't shameful. It's a tool with a price — find the price first.","route":"#/atlas/c6a","cta":"Open the lesson","maths":"M10","source":"Chapter 6 · Borrowing · with Nana Bizz","id":"f-card-c6a-eg","bands":["builder"],"grp":"card:c6a"},"f-lesson-c6a-beats0-1":{"kind":"line","src":"lesson:c6a#beats0-1","level":6,"topics":["card:c6a","ch:c6","who:nana"],"title":"Interest, both ways","body":"Interest is rent — rent on money. And it runs both ways.\nLeave money with a bank, and they pay you rent for using it.","route":"#/atlas/c6a","cta":"Watch the lesson","maths":"M10","source":"Chapter 6 · Borrowing · with Nana Bizz","id":"f-lesson-c6a-beats0-1","bands":["sprout","builder"],"grp":"card:c6a"},"f-lesson-c6a-beats2-4":{"kind":"line","src":"lesson:c6a#beats2-4","level":6,"topics":["card:c6a","ch:c6","who:nana"],"title":"Interest, both ways","body":"Borrow money, and you pay rent for using theirs.\nSame idea. Which side you stand on makes all the difference.\nBorrowing is not shameful. It is a tool with a price on it — and you always, always find the price before you agree.","route":"#/atlas/c6a","cta":"Watch the lesson","maths":"M10","source":"Chapter 6 · Borrowing · with Nana Bizz","id":"f-lesson-c6a-beats2-4","bands":["sprout","builder"],"grp":"card:c6a"},"f-card-c6a-q0":{"kind":"question","src":"card:c6a#q0","level":6,"topics":["card:c6a","ch:c6","who:nana"],"key":"c6a#0","title":"Interest, both ways","play":{"q":"What is the honest way to describe interest on a loan?","opts":["The rent you pay for using somebody else’s money","A tax","A punishment for being bad with money","A fee the shop keeps"],"after":"Credit is a tool with a price, not a moral failing. Knowing the price is the skill."},"route":"#/atlas/c6a","cta":"Open the lesson","maths":"M10","source":"Chapter 6 · Borrowing · with Nana Bizz","id":"f-card-c6a-q0","bands":["sprout","builder"],"grp":"card:c6a"},"f-card-c6a-q1":{"kind":"question","src":"card:c6a#q1","level":6,"topics":["card:c6a","ch:c6","who:nana"],"key":"c6a#1","title":"Interest, both ways","play":{"q":"Interest is best described as…","opts":["Rent paid on money","A tax on savings","A tip for the bank","A fine for being poor"],"after":"Rent on money, running both ways: they rent yours, you rent theirs."},"route":"#/atlas/c6a","cta":"Open the lesson","maths":"M10","source":"Chapter 6 · Borrowing · with Nana Bizz","id":"f-card-c6a-q1","bands":["sprout","builder"],"grp":"card:c6a"},"f-card-c6a-q2":{"kind":"question","src":"card:c6a#q2","level":6,"topics":["card:c6a","ch:c6","who:nana"],"key":"c6a#2","title":"Interest, both ways","play":{"q":"What must you ALWAYS do before agreeing to borrow?","opts":["Find the full price of it","Feel ashamed about it","Wait a whole week","Ask two banks at least"],"after":"Borrowing is a tool with a price. Find the price first — always."},"route":"#/atlas/c6a","cta":"Open the lesson","maths":"M10","source":"Chapter 6 · Borrowing · with Nana Bizz","id":"f-card-c6a-q2","bands":["sprout","builder"],"grp":"card:c6a"},"f-card-c6a-why0":{"kind":"why","src":"card:c6a#why0","level":6,"topics":["card:c6a","ch:c6","who:nana"],"card":"c6a","title":"Interest, both ways","body":"Credit is a tool with a price, not a moral failing. Knowing the price is the skill.","route":"#/atlas/c6a","cta":"Open the lesson","maths":"M10","source":"Chapter 6 · Borrowing · with Nana Bizz","id":"f-card-c6a-why0","bands":["sprout","builder"],"grp":"card:c6a"},"f-card-c6a-why1":{"kind":"why","src":"card:c6a#why1","level":6,"topics":["card:c6a","ch:c6","who:nana"],"card":"c6a","title":"Interest, both ways","body":"Rent on money, running both ways: they rent yours, you rent theirs.","route":"#/atlas/c6a","cta":"Open the lesson","maths":"M10","source":"Chapter 6 · Borrowing · with Nana Bizz","id":"f-card-c6a-why1","bands":["sprout","builder"],"grp":"card:c6a"},"f-item-c6a":{"kind":"yourturn","src":"item:c6a","level":6,"topics":["card:c6a","ch:c6","who:nana"],"title":"Your turn","body":"Who pays the rent on money?\nInterest is rent on money. Whoever is using someone else’s money pays it.","route":"#/atlas/c6a","cta":"Have a go","maths":"M10","source":"Chapter 6 · Borrowing · Interest, both ways · with Nana Bizz","id":"f-item-c6a","bands":["sprout","builder"],"grp":"card:c6a"},"f-card-c6b-teach":{"kind":"lesson","src":"card:c6b#teach","level":6,"topics":["card:c6b","ch:c6","who:pip"],"title":"The number that matters","body":"Sellers show the small monthly payment. The truth is everything you pay back in total, minus what you borrowed.","route":"#/atlas/c6b","cta":"Open the lesson","maths":"M9","card":"c6b","source":"Chapter 6 · Borrowing · with Pip","id":"f-card-c6b-teach","bands":["builder"],"grp":"card:c6b"},"f-card-c6b-eg":{"kind":"example","src":"card:c6b#eg","level":6,"topics":["card:c6b","ch:c6","who:pip"],"title":"The number that matters","body":"Borrow 1,000, repay 110 a month for a year: you pay 1,320. It cost 320.","route":"#/atlas/c6b","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · with Pip","id":"f-card-c6b-eg","bands":["builder"],"grp":"card:c6b"},"f-lesson-c6b-beats0-1":{"kind":"line","src":"lesson:c6b#beats0-1","level":6,"topics":["card:c6b","ch:c6","who:pip"],"title":"The number that matters","body":"Sellers quote the monthly payment, because the monthly payment is small.\nThe number that tells the truth is bigger and quieter: everything you will hand over, minus what you borrowed.","route":"#/atlas/c6b","cta":"Watch the lesson","maths":"M9","source":"Chapter 6 · Borrowing · with Pip","id":"f-lesson-c6b-beats0-1","bands":["sprout","builder"],"grp":"card:c6b"},"f-lesson-c6b-beats2-4":{"kind":"line","src":"lesson:c6b#beats2-4","level":6,"topics":["card:c6b","ch:c6","who:pip"],"title":"The number that matters","body":"Borrow a thousand. Pay back one hundred and ten a month, for a year.\nYou handed over one thousand, three hundred and twenty.\nIt cost three hundred and twenty. THAT is the number. Ask for it by name.","route":"#/atlas/c6b","cta":"Watch the lesson","maths":"M9","source":"Chapter 6 · Borrowing · with Pip","id":"f-lesson-c6b-beats2-4","bands":["sprout","builder"],"grp":"card:c6b"},"f-card-c6b-q0":{"kind":"question","src":"card:c6b#q0","level":6,"topics":["card:c6b","ch:c6","who:pip"],"key":"c6b#0","title":"The number that matters","play":{"q":"You borrow 500 and repay 60 a month for ten months. What did borrowing cost?","opts":["100","500","Nothing","60"],"after":"60 × 10 = 600, minus the 500 borrowed = 100. Do that sum before you sign."},"route":"#/atlas/c6b","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · with Pip","id":"f-card-c6b-q0","bands":["sprout","builder"],"grp":"card:c6b"},"f-card-c6b-q1":{"kind":"question","src":"card:c6b#q1","level":6,"topics":["card:c6b","ch:c6","who:pip"],"key":"c6b#1","title":"Borrowing","play":{"q":"Why do sellers quote the monthly payment instead of the total?","opts":["Small numbers hide the cost","Totals are hard to compute","Monthly is the legal format","Banks set the rules"],"after":"110 a month sounds gentle. 1,320 handed over for 1,000 borrowed — 320 of cost — does not."},"route":"#/atlas/c6b","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · with Pip","id":"f-card-c6b-q1","bands":["sprout","builder"],"grp":"card:c6b"},"f-card-c6b-q2":{"kind":"question","src":"card:c6b#q2","level":6,"topics":["card:c6b","ch:c6","who:pip"],"key":"c6b#2","title":"The number that matters","play":{"q":"Borrow 1,000 and hand over 1,320 in total. What did the loan cost?","opts":["320","110","1,320","1,000"],"after":"Everything handed over, minus what you borrowed. That gap is the price of the loan."},"route":"#/atlas/c6b","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · with Pip","id":"f-card-c6b-q2","bands":["sprout","builder"],"grp":"card:c6b"},"f-card-c6b-why0":{"kind":"why","src":"card:c6b#why0","level":6,"topics":["card:c6b","ch:c6","who:pip"],"card":"c6b","title":"The number that matters","body":"60 × 10 = 600, minus the 500 borrowed = 100. Do that sum before you sign.","route":"#/atlas/c6b","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · with Pip","id":"f-card-c6b-why0","bands":["sprout","builder"],"grp":"card:c6b"},"f-card-c6b-why1":{"kind":"why","src":"card:c6b#why1","level":6,"topics":["card:c6b","ch:c6","who:pip"],"card":"c6b","title":"The number that matters","body":"110 a month sounds gentle. 1,320 handed over for 1,000 borrowed — 320 of cost — does not.","route":"#/atlas/c6b","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · with Pip","id":"f-card-c6b-why1","bands":["sprout","builder"],"grp":"card:c6b"},"f-card-c6b-why2":{"kind":"why","src":"card:c6b#why2","level":6,"topics":["card:c6b","ch:c6","who:pip"],"card":"c6b","title":"The number that matters","body":"Everything handed over, minus what you borrowed. That gap is the price of the loan.","route":"#/atlas/c6b","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · with Pip","id":"f-card-c6b-why2","bands":["sprout","builder"],"grp":"card:c6b"},"f-item-c6b":{"kind":"yourturn","src":"item:c6b","level":6,"topics":["card:c6b","ch:c6","who:pip"],"title":"Your turn","body":"What the loan really cost\nAdd up everything handed back, then take away what was borrowed.","route":"#/atlas/c6b","cta":"Have a go","maths":"M9","source":"Chapter 6 · Borrowing · The number that matters · with Pip","id":"f-item-c6b","bands":["sprout","builder"],"grp":"card:c6b"},"f-tryit-c6b":{"kind":"tryit","src":"tryit:c6b","level":6,"topics":["card:c6b","ch:c6","who:pip"],"title":"Try it","body":"What a loan really costs","route":"#/atlas/c6b","cta":"Change the numbers","maths":"M9","source":"Chapter 6 · Borrowing · The number that matters · with Pip","id":"f-tryit-c6b","bands":["sprout","builder"],"grp":"card:c6b"},"f-card-c6c-teach":{"kind":"lesson","src":"card:c6c#teach","level":6,"topics":["card:c6c","ch:c6","who:nana"],"title":"Good reasons and bad ones","body":"Borrowing for something that earns or lasts — a tool, a roof — can make sense. Borrowing for something gone by Friday is paying rent on a memory.","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","card":"c6c","source":"Chapter 6 · Borrowing · with Nana Bizz","id":"f-card-c6c-teach","bands":["sprout","builder"],"grp":"card:c6c"},"f-card-c6c-eg":{"kind":"example","src":"card:c6c#eg","level":6,"topics":["card:c6c","ch:c6","who:nana"],"title":"Good reasons and bad ones","body":"Nana's loan for umbrella stock made money. Her festival loan didn't — and she'd do it again anyway.","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","source":"Chapter 6 · Borrowing · with Nana Bizz","id":"f-card-c6c-eg","bands":["builder"],"grp":"card:c6c"},"f-lesson-c6c-beat0":{"kind":"line","src":"lesson:c6c#beat0","level":6,"topics":["card:c6c","ch:c6","who:nana"],"title":"Good reasons and bad ones","body":"Borrowing has good reasons and bad ones, and there is a simple way to tell them apart.","route":"#/atlas/c6c","cta":"Watch the lesson","maths":"M4","source":"Chapter 6 · Borrowing · with Nana Bizz","id":"f-lesson-c6c-beat0","bands":["sprout","builder"],"grp":"card:c6c"},"f-lesson-c6c-beat1":{"kind":"line","src":"lesson:c6c#beat1","level":6,"topics":["card:c6c","ch:c6","who:nana"],"title":"Good reasons and bad ones","body":"A tool. A course. A roof. Things that earn, or last — borrowing for those can be sensible, even with the rent on top.","route":"#/atlas/c6c","cta":"Watch the lesson","maths":"M4","source":"Chapter 6 · Borrowing · with Nana Bizz","id":"f-lesson-c6c-beat1","bands":["sprout","builder"],"grp":"card:c6c"},"f-lesson-c6c-beats3-4":{"kind":"line","src":"lesson:c6c#beats3-4","level":6,"topics":["card:c6c","ch:c6","who:nana"],"title":"Good reasons and bad ones","body":"A loan for umbrella stock made me money. A loan for the festival did not.\nAnd I would take the festival one again anyway. Just — knowingly.","route":"#/atlas/c6c","cta":"Watch the lesson","maths":"M4","source":"Chapter 6 · Borrowing · with Nana Bizz","id":"f-lesson-c6c-beats3-4","bands":["sprout","builder"],"grp":"card:c6c"},"f-card-c6c-q0":{"kind":"question","src":"card:c6c#q0","level":6,"topics":["card:c6c","ch:c6","who:nana"],"key":"c6c#0","title":"Good reasons and bad ones","play":{"q":"Which is the more defensible reason to borrow?","opts":["A tool that lets you take on paid work","A weekend away","Because the offer was there","A better phone than your friend’s"],"after":"Not a rule about fun — a question. Will it still be worth something while you're still paying?"},"route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","source":"Chapter 6 · Borrowing · with Nana Bizz","id":"f-card-c6c-q0","bands":["sprout","builder"],"grp":"card:c6c"},"f-card-c6c-q1":{"kind":"question","src":"card:c6c#q1","level":6,"topics":["card:c6c","ch:c6","who:nana"],"key":"c6c#1","title":"Good reasons and bad ones","play":{"q":"Which of these is borrowing for a thing that is \"gone by Friday\"?","opts":["A feast for the festival","A stall roof repair","A crate-carrying trolley","A bread-baking course"],"after":"The roof, the trolley and the course all last or earn. The feast is a memory paying rent."},"route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","source":"Chapter 6 · Borrowing · with Nana Bizz","id":"f-card-c6c-q1","bands":["sprout","builder"],"grp":"card:c6c"},"f-card-c6c-q2":{"kind":"question","src":"card:c6c#q2","level":6,"topics":["card:c6c","ch:c6","who:nana"],"key":"c6c#2","title":"Good reasons and bad ones","play":{"q":"Nana borrowed for umbrella stock AND for the festival. What did she say about the festival loan?","opts":["She would do it again, knowingly","The bank forgave it","It was her best investment","She regrets it bitterly"],"after":"It made no money and she would do it again — the point is doing it knowingly."},"route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","source":"Chapter 6 · Borrowing · with Nana Bizz","id":"f-card-c6c-q2","bands":["sprout","builder"],"grp":"card:c6c"},"f-card-c6c-why0":{"kind":"why","src":"card:c6c#why0","level":6,"topics":["card:c6c","ch:c6","who:nana"],"card":"c6c","title":"Good reasons and bad ones","body":"Not a rule about fun — a question. Will it still be worth something while you're still paying?","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","source":"Chapter 6 · Borrowing · with Nana Bizz","id":"f-card-c6c-why0","bands":["sprout","builder"],"grp":"card:c6c"},"f-card-c6c-why1":{"kind":"why","src":"card:c6c#why1","level":6,"topics":["card:c6c","ch:c6","who:nana"],"card":"c6c","title":"Good reasons and bad ones","body":"The roof, the trolley and the course all last or earn. The feast is a memory paying rent.","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","source":"Chapter 6 · Borrowing · with Nana Bizz","id":"f-card-c6c-why1","bands":["sprout","builder"],"grp":"card:c6c"},"f-card-c6c-why2":{"kind":"why","src":"card:c6c#why2","level":6,"topics":["card:c6c","ch:c6","who:nana"],"card":"c6c","title":"Good reasons and bad ones","body":"It made no money and she would do it again — the point is doing it knowingly.","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","source":"Chapter 6 · Borrowing · with Nana Bizz","id":"f-card-c6c-why2","bands":["sprout","builder"],"grp":"card:c6c"},"f-item-c6c":{"kind":"yourturn","src":"item:c6c","level":6,"topics":["card:c6c","ch:c6","who:nana"],"title":"Your turn","body":"Earns or lasts — or gone by Friday?\nAsk: will this still be paying me back, or still standing, after the loan is paid?","route":"#/atlas/c6c","cta":"Have a go","maths":"M4","source":"Chapter 6 · Borrowing · Good reasons and bad ones · with Nana Bizz","id":"f-item-c6c","bands":["sprout","builder"],"grp":"card:c6c"},"f-card-c6d-teach":{"kind":"lesson","src":"card:c6d#teach","level":6,"topics":["card:c6d","ch:c6","who:pip"],"title":"Trust is a memory","body":"Lenders remember who paid them back. A good record makes borrowing cheaper. It's a memory of what happened, not who you are — and it can be rebuilt.","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","card":"c6d","source":"Chapter 6 · Borrowing · with Pip","id":"f-card-c6d-teach","bands":["sprout","builder"],"grp":"card:c6d"},"f-card-c6d-eg":{"kind":"example","src":"card:c6d#eg","level":6,"topics":["card:c6d","ch:c6","who:pip"],"title":"Trust is a memory","body":"Here it's the trust score. It goes up every time you repay.","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","source":"Chapter 6 · Borrowing · with Pip","id":"f-card-c6d-eg","bands":["builder"],"grp":"card:c6d"},"f-lesson-c6d-beats0-1":{"kind":"line","src":"lesson:c6d#beats0-1","level":6,"topics":["card:c6d","ch:c6","who:pip"],"title":"Trust is a memory","body":"Lenders keep a record of one thing only: whether people paid them back.\nA good record makes borrowing cheaper later. A bad one makes it dearer.","route":"#/atlas/c6d","cta":"Watch the lesson","maths":"M5","source":"Chapter 6 · Borrowing · with Pip","id":"f-lesson-c6d-beats0-1","bands":["sprout","builder"],"grp":"card:c6d"},"f-lesson-c6d-beats2-4":{"kind":"line","src":"lesson:c6d#beats2-4","level":6,"topics":["card:c6d","ch:c6","who:pip"],"title":"Trust is a memory","body":"Bizzington calls it a trust score. It goes up every time you repay.\nIt is a memory of what happened — not a score of what kind of person you are.\nAnd a memory can be rebuilt. One repayment at a time.","route":"#/atlas/c6d","cta":"Watch the lesson","maths":"M5","source":"Chapter 6 · Borrowing · with Pip","id":"f-lesson-c6d-beats2-4","bands":["sprout","builder"],"grp":"card:c6d"},"f-card-c6d-q0":{"kind":"question","src":"card:c6d#q0","level":6,"topics":["card:c6d","ch:c6","who:pip"],"key":"c6d#0","title":"Trust is a memory","play":{"q":"What does a lender’s record of you actually describe?","opts":["Whether past borrowing was repaid","Whether you deserve help","How much money you have","How hard you work"],"after":"Good people can have bad records after a bad year. Records can be added to."},"route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","source":"Chapter 6 · Borrowing · with Pip","id":"f-card-c6d-q0","bands":["sprout","builder"],"grp":"card:c6d"},"f-card-c6d-q1":{"kind":"question","src":"card:c6d#q1","level":6,"topics":["card:c6d","ch:c6","who:pip"],"key":"c6d#1","title":"Trust is a memory","play":{"q":"What does a trust score actually record?","opts":["Whether you repaid your loans","How much money you keep saved","How often you visit the bank","What kind of person you are"],"after":"A memory of what happened — never a judgement of who you are."},"route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","source":"Chapter 6 · Borrowing · with Pip","id":"f-card-c6d-q1","bands":["sprout","builder"],"grp":"card:c6d"},"f-card-c6d-q2":{"kind":"question","src":"card:c6d#q2","level":6,"topics":["card:c6d","ch:c6","who:pip"],"key":"c6d#2","title":"Trust is a memory","play":{"q":"Your record has some bad marks. What does the card say about that?","opts":["Repaying rebuilds it over time","It follows you forever","You must change banks now","Only cash from here on"],"after":"The memory can be rebuilt — up every time you repay, and it never says anything about you."},"route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","source":"Chapter 6 · Borrowing · with Pip","id":"f-card-c6d-q2","bands":["sprout","builder"],"grp":"card:c6d"},"f-card-c6d-why0":{"kind":"why","src":"card:c6d#why0","level":6,"topics":["card:c6d","ch:c6","who:pip"],"card":"c6d","title":"Trust is a memory","body":"Good people can have bad records after a bad year. Records can be added to.","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","source":"Chapter 6 · Borrowing · with Pip","id":"f-card-c6d-why0","bands":["sprout","builder"],"grp":"card:c6d"},"f-card-c6d-why2":{"kind":"why","src":"card:c6d#why2","level":6,"topics":["card:c6d","ch:c6","who:pip"],"card":"c6d","title":"Trust is a memory","body":"The memory can be rebuilt — up every time you repay, and it never says anything about you.","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","source":"Chapter 6 · Borrowing · with Pip","id":"f-card-c6d-why2","bands":["sprout","builder"],"grp":"card:c6d"},"f-item-c6d":{"kind":"yourturn","src":"item:c6d","level":6,"topics":["card:c6d","ch:c6","who:pip"],"title":"Your turn","body":"What a trust score remembers\nIt is a memory of what happened with loans — never a judgement of who you are.","route":"#/atlas/c6d","cta":"Have a go","maths":"M5","source":"Chapter 6 · Borrowing · Trust is a memory · with Pip","id":"f-item-c6d","bands":["sprout","builder"],"grp":"card:c6d"},"f-card-c6e-teach":{"kind":"lesson","src":"card:c6e#teach","level":6,"topics":["card:c6e","ch:c6","who:nana"],"title":"Can the payment fit?","body":"Before you borrow, ask a better question than “will they lend to me?” Ask “does the payment fit in what is left each week — even a slow one?” A payment you promised comes before a want.","route":"#/atlas/c6e","cta":"Open the lesson","maths":"M10","card":"c6e","source":"Chapter 6 · Borrowing · with Nana Bizz","id":"f-card-c6e-teach","bands":["sprout","builder"],"grp":"card:c6e"},"f-card-c6e-eg":{"kind":"example","src":"card:c6e#eg","level":6,"topics":["card:c6e","ch:c6","who:nana"],"title":"Can the payment fit?","body":"Bea has 50 in and 30 of costs each week, so 20 is left. A payment of 12 fits, with 8 to spare. A payment of 25 does not.","route":"#/atlas/c6e","cta":"Open the lesson","maths":"M10","source":"Chapter 6 · Borrowing · with Nana Bizz","id":"f-card-c6e-eg","bands":["sprout","builder"],"grp":"card:c6e"},"f-card-c6e-q0":{"kind":"question","src":"card:c6e#q0","level":6,"topics":["card:c6e","ch:c6","who:nana"],"key":"c6e#0","title":"Can the payment fit?","play":{"q":"Each week you have 40 in and 34 of costs. A loan wants 10 a week. What is true?","opts":["It does not fit, as only 6 is left","It fits if you skip some costs","Payments do not count as costs","It fits easily"],"after":"40 take away 34 leaves 6, and the payment is 10. Borrowing would mean missing payments from the first week."},"route":"#/atlas/c6e","cta":"Open the lesson","maths":"M10","source":"Chapter 6 · Borrowing · with Nana Bizz","id":"f-card-c6e-q0","bands":["sprout","builder"],"grp":"card:c6e"},"f-card-c6e-q1":{"kind":"question","src":"card:c6e#q1","level":6,"topics":["card:c6e","ch:c6","who:nana"],"key":"c6e#1","title":"Can the payment fit?","play":{"q":"A payment fits in a good week but not in a slow one. What does that mean?","opts":["It does not really fit","Only pay in the good weeks","Borrow more to cover it","It fits, because good weeks count"],"after":"A payment comes every week, slow ones too. Plan it on the slow week, like any other cost."},"route":"#/atlas/c6e","cta":"Open the lesson","maths":"M10","source":"Chapter 6 · Borrowing · with Nana Bizz","id":"f-card-c6e-q1","bands":["sprout","builder"],"grp":"card:c6e"},"f-card-c6e-q2":{"kind":"question","src":"card:c6e#q2","level":6,"topics":["card:c6e","ch:c6","who:nana"],"key":"c6e#2","title":"Can the payment fit?","play":{"q":"A treat and your loan payment both want the same 10 this week. Which comes first?","opts":["The loan payment","Split it half and half","The treat, it is your money","Whichever you see first"],"after":"The payment is a promise you already made. Keeping it is what keeps borrowing cheaper next time."},"route":"#/atlas/c6e","cta":"Open the lesson","maths":"M10","source":"Chapter 6 · Borrowing · with Nana Bizz","id":"f-card-c6e-q2","bands":["sprout","builder"],"grp":"card:c6e"},"f-card-c6e-why0":{"kind":"why","src":"card:c6e#why0","level":6,"topics":["card:c6e","ch:c6","who:nana"],"card":"c6e","title":"Can the payment fit?","body":"40 take away 34 leaves 6, and the payment is 10. Borrowing would mean missing payments from the first week.","route":"#/atlas/c6e","cta":"Open the lesson","maths":"M10","source":"Chapter 6 · Borrowing · with Nana Bizz","id":"f-card-c6e-why0","bands":["sprout","builder"],"grp":"card:c6e"},"f-card-c6e-why1":{"kind":"why","src":"card:c6e#why1","level":6,"topics":["card:c6e","ch:c6","who:nana"],"card":"c6e","title":"Can the payment fit?","body":"A payment comes every week, slow ones too. Plan it on the slow week, like any other cost.","route":"#/atlas/c6e","cta":"Open the lesson","maths":"M10","source":"Chapter 6 · Borrowing · with Nana Bizz","id":"f-card-c6e-why1","bands":["sprout","builder"],"grp":"card:c6e"},"f-card-c6e-why2":{"kind":"why","src":"card:c6e#why2","level":6,"topics":["card:c6e","ch:c6","who:nana"],"card":"c6e","title":"Can the payment fit?","body":"The payment is a promise you already made. Keeping it is what keeps borrowing cheaper next time.","route":"#/atlas/c6e","cta":"Open the lesson","maths":"M10","source":"Chapter 6 · Borrowing · with Nana Bizz","id":"f-card-c6e-why2","bands":["sprout","builder"],"grp":"card:c6e"},"f-item-c6e":{"kind":"yourturn","src":"item:c6e","level":6,"topics":["card:c6e","ch:c6","who:nana"],"title":"Your turn","body":"What is left after the payment\nTake the costs away first, then the payment. What remains is the part she chooses about.","route":"#/atlas/c6e","cta":"Have a go","maths":"M10","source":"Chapter 6 · Borrowing · Can the payment fit? · with Nana Bizz","id":"f-item-c6e","bands":["sprout","builder"],"grp":"card:c6e"},"f-card-c6f-teach":{"kind":"lesson","src":"card:c6f#teach","level":6,"topics":["card:c6f","ch:c6","who:pip"],"title":"Lending to a friend","body":"Lending to a friend is kind, and it goes best with three plain steps: lend only what you could manage without, agree out loud when it comes back, and write it down where you both can see.","route":"#/atlas/c6f","cta":"Open the lesson","maths":"M10","card":"c6f","source":"Chapter 6 · Borrowing · with Pip","id":"f-card-c6f-teach","bands":["sprout","builder"],"grp":"card:c6f"},"f-card-c6f-eg":{"kind":"example","src":"card:c6f#eg","level":6,"topics":["card:c6f","ch:c6","who:pip"],"title":"Lending to a friend","body":"Chhoti borrowed 20 from Pip for a book. They wrote “20, back by Friday” in his notebook. Friday came, and so did the 20.","route":"#/atlas/c6f","cta":"Open the lesson","maths":"M10","source":"Chapter 6 · Borrowing · with Pip","id":"f-card-c6f-eg","bands":["sprout","builder"],"grp":"card:c6f"},"f-card-c6f-q0":{"kind":"question","src":"card:c6f#q0","level":6,"topics":["card:c6f","ch:c6","who:pip"],"key":"c6f#0","title":"Lending to a friend","play":{"q":"Why lend a friend only what you could manage without?","opts":["So a late payback hurts nobody","Because friends never pay back","Because lending is wrong","So you can ask for more back"],"after":"If it comes back late, you are fine and so is the friendship. Lending what you cannot spare turns a delay into a quarrel."},"route":"#/atlas/c6f","cta":"Open the lesson","maths":"M10","source":"Chapter 6 · Borrowing · with Pip","id":"f-card-c6f-q0","bands":["sprout","builder"],"grp":"card:c6f"},"f-card-c6f-q1":{"kind":"question","src":"card:c6f#q1","level":6,"topics":["card:c6f","ch:c6","who:pip"],"key":"c6f#1","title":"Lending to a friend","play":{"q":"Why write down “20, back by Friday”?","opts":["So nobody has to remember or argue","So you can add interest later","Because the bank needs a copy","To show your other friends"],"after":"Memories differ. A note you both saw keeps the money simple and the friendship easy."},"route":"#/atlas/c6f","cta":"Open the lesson","maths":"M10","source":"Chapter 6 · Borrowing · with Pip","id":"f-card-c6f-q1","bands":["sprout","builder"],"grp":"card:c6f"},"f-card-c6f-q2":{"kind":"question","src":"card:c6f#q2","level":6,"topics":["card:c6f","ch:c6","who:pip"],"key":"c6f#2","title":"Lending to a friend","play":{"q":"Friday comes and your friend has not paid you back. What is a good first step?","opts":["Remind them kindly and agree a new day","Tell everyone at school","Never speak to them again","Take something of theirs"],"after":"Late is not the same as never. A kind reminder and a new day usually sort it out."},"route":"#/atlas/c6f","cta":"Open the lesson","maths":"M10","source":"Chapter 6 · Borrowing · with Pip","id":"f-card-c6f-q2","bands":["sprout","builder"],"grp":"card:c6f"},"f-card-c6f-why0":{"kind":"why","src":"card:c6f#why0","level":6,"topics":["card:c6f","ch:c6","who:pip"],"card":"c6f","title":"Lending to a friend","body":"If it comes back late, you are fine and so is the friendship. Lending what you cannot spare turns a delay into a quarrel.","route":"#/atlas/c6f","cta":"Open the lesson","maths":"M10","source":"Chapter 6 · Borrowing · with Pip","id":"f-card-c6f-why0","bands":["sprout","builder"],"grp":"card:c6f"},"f-card-c6f-why1":{"kind":"why","src":"card:c6f#why1","level":6,"topics":["card:c6f","ch:c6","who:pip"],"card":"c6f","title":"Lending to a friend","body":"Memories differ. A note you both saw keeps the money simple and the friendship easy.","route":"#/atlas/c6f","cta":"Open the lesson","maths":"M10","source":"Chapter 6 · Borrowing · with Pip","id":"f-card-c6f-why1","bands":["sprout","builder"],"grp":"card:c6f"},"f-card-c6f-why2":{"kind":"why","src":"card:c6f#why2","level":6,"topics":["card:c6f","ch:c6","who:pip"],"card":"c6f","title":"Lending to a friend","body":"Late is not the same as never. A kind reminder and a new day usually sort it out.","route":"#/atlas/c6f","cta":"Open the lesson","maths":"M10","source":"Chapter 6 · Borrowing · with Pip","id":"f-card-c6f-why2","bands":["sprout","builder"],"grp":"card:c6f"},"f-item-c6f":{"kind":"yourturn","src":"item:c6f","level":6,"topics":["card:c6f","ch:c6","who:pip"],"title":"Your turn","body":"Lending it the friendly way\nWork out what you can spare before anything changes hands. The reminder comes last.","route":"#/atlas/c6f","cta":"Have a go","maths":"M10","source":"Chapter 6 · Borrowing · Lending to a friend · with Pip","id":"f-item-c6f","bands":["sprout","builder"],"grp":"card:c6f"},"f-card-x-ch8-teach":{"kind":"lesson","src":"card:x-ch8#teach","level":6,"topics":["card:x-ch8","ch:c6","who:nana"],"title":"What waiting costs, and what it saves","body":"Buying now and saving up are both real answers. The honest way to choose is to write down both columns: what you pay extra by buying now, and what you give up by waiting. Then pick — and you will actually know why.","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","card":"x-ch8","source":"Chapter 6 · Borrowing · with Nana Bizz","id":"f-card-x-ch8-teach","bands":["builder"],"grp":"card:x-ch8"},"f-card-x-ch8-eg":{"kind":"example","src":"card:x-ch8#eg","level":6,"topics":["card:x-ch8","ch:c6","who:nana"],"title":"What waiting costs, and what it saves","body":"The kit is ₹800. You have ₹500. Wait three weeks and it costs ₹800. Borrow and it costs ₹880 — and you had it for three weeks. Eighty rupees is the price of three weeks. Sometimes that is worth it. Sometimes it is not.","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · with Nana Bizz","id":"f-card-x-ch8-eg","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-card-x-ch8-q0":{"kind":"question","src":"card:x-ch8#q0","level":6,"topics":["card:x-ch8","ch:c6","who:nana"],"key":"x-ch8#0","title":"What waiting costs, and what it saves","play":{"q":"When is waiting the better choice?","opts":["When three weeks of having it matters less to you than ₹80","Always — waiting is the careful answer","When three weeks of having it matters more to you than ₹80","Never, if you can afford the payments"],"after":"There is no rule that says wait. There is a comparison — the extra you pay against the time you gain — and either answer can be right once you have actually made it."},"route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · with Nana Bizz","id":"f-card-x-ch8-q0","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-card-x-ch8-why0":{"kind":"why","src":"card:x-ch8#why0","level":6,"topics":["card:x-ch8","ch:c6","who:nana"],"card":"x-ch8","title":"What waiting costs, and what it saves","body":"There is no rule that says wait. There is a comparison — the extra you pay against the time you gain — and either answer can be right once you have actually made it.","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · with Nana Bizz","id":"f-card-x-ch8-why0","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-chapter-c6":{"kind":"chapter","src":"chapter:c6","level":6,"topics":["ch:c6"],"title":"Borrowing","body":"What credit costs, why it exists, and why it is never a verdict on a person.","route":"#/atlas/chapter/c6","cta":"The Money Atlas","maths":"M10","source":"Chapter 6 of 8 · 6 lessons on the Money Atlas","id":"f-chapter-c6","bands":["sprout","builder"],"grp":"chapter:c6"},"f-goal-choose-8":{"kind":"goal","src":"goal:CHOOSE-8","level":6,"topics":["card:x-ch8","ch:c6"],"title":"Weighing waiting against buying now","body":"Compares buying now against saving up by writing both columns — the extra paid now, and the time given up by waiting — and can defend either answer.","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M6","source":"Chapter 6 · Borrowing · what the lesson is for","id":"f-goal-choose-8","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-goal-grow-2":{"kind":"goal","src":"goal:GROW-2","level":6,"topics":["card:c6a","ch:c6"],"title":"Interest, in coins","body":"Works out one period's interest on a balance, and can say it in coins as well as as a rate.","route":"#/atlas/c6a","cta":"Open the lesson","maths":"M10","source":"Chapter 6 · Borrowing · what the lesson is for","id":"f-goal-grow-2","bands":["sprout","builder"],"grp":"card:c6a"},"f-goal-owe-1":{"kind":"goal","src":"goal:OWE-1","level":6,"topics":["card:c6a","ch:c6"],"title":"Borrowing has a price","body":"Says that borrowing has a price and names it, without treating borrowing itself as a wrong thing.","route":"#/atlas/c6a","cta":"Open the lesson","maths":"M6","source":"Chapter 6 · Borrowing · what the lesson is for","id":"f-goal-owe-1","bands":["sprout","builder"],"grp":"card:c6a"},"f-goal-owe-2":{"kind":"goal","src":"goal:OWE-2","level":6,"topics":["card:c6b","ch:c6"],"title":"The number that matters","body":"Reads the total they will hand over before agreeing, rather than the size of the weekly payment.","route":"#/atlas/c6b","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · what the lesson is for","id":"f-goal-owe-2","bands":["sprout","builder"],"grp":"card:c6b"},"f-goal-owe-3":{"kind":"goal","src":"goal:OWE-3","level":6,"topics":["card:c6c","ch:c6"],"title":"Good reasons and bad ones","body":"Names a good reason and a bad reason to borrow from their own situation, not from a general rule.","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","source":"Chapter 6 · Borrowing · what the lesson is for","id":"f-goal-owe-3","bands":["sprout","builder"],"grp":"card:c6c"},"f-goal-owe-4":{"kind":"goal","src":"goal:OWE-4","level":6,"topics":["card:c6d","ch:c6"],"title":"Paying it when you would rather not","body":"Makes a repayment when something else wants the money, and names what they gave up to make it.","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","source":"Chapter 6 · Borrowing · what the lesson is for","id":"f-goal-owe-4","bands":["sprout","builder"],"grp":"card:c6d"},"f-goal-owe-5":{"kind":"goal","src":"goal:OWE-5","level":6,"topics":["card:c6d","ch:c6"],"title":"Trust is a memory","body":"Says how what they can borrow next time changes, in both directions, according to what they did this time.","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M4","source":"Chapter 6 · Borrowing · what the lesson is for","id":"f-goal-owe-5","bands":["sprout","builder"],"grp":"card:c6d"},"f-goal-owe-6":{"kind":"goal","src":"goal:OWE-6","level":6,"topics":["card:x-ch8","ch:c6"],"title":"Waiting against borrowing","body":"Puts the cost of waiting and the cost of borrowing in the same units before choosing between them.","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · what the lesson is for","id":"f-goal-owe-6","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-word-credit":{"kind":"word","src":"word:Credit","level":6,"topics":["word","word:Credit","ch:c6"],"title":"Credit","body":"Borrowed money.","route":"#/words/Credit","cta":"Money Words","source":"Money Words · first used in Chapter 6 · Borrowing","id":"f-word-credit","bands":["sprout","builder"],"maths":"M1","because":"A money word first used in Chapter 6 · Borrowing","grp":"word:Credit"},"f-word-credit-more":{"kind":"wordmore","src":"word:Credit#more","level":6,"topics":["word","word:Credit","ch:c6"],"title":"Credit","body":"A tool with a price on it, never a verdict on a person.","route":"#/words/Credit","cta":"Money Words","source":"Money Words · first used in Chapter 6 · Borrowing","id":"f-word-credit-more","bands":["sprout","builder"],"maths":"M1","because":"A money word first used in Chapter 6 · Borrowing","grp":"word:Credit"},"f-word-trust-score":{"kind":"word","src":"word:Trust score","level":6,"topics":["word","word:Trust score","ch:c6"],"title":"Trust score","body":"A record of whether past borrowing was repaid.","route":"#/words/Trust%20score","cta":"Money Words","source":"Money Words · first used in Chapter 6 · Borrowing","id":"f-word-trust-score","bands":["sprout","builder"],"maths":"M1","because":"A money word first used in Chapter 6 · Borrowing","grp":"word:Trust score"},"f-figure-loan":{"kind":"figure","src":"figure:loan","level":6,"topics":["figure","ch:c6"],"badge":{"id":"own","label":"A dial of this town"},"title":"What a Bank loan costs","body":"about 1% of the loan for each week you borrow, a little less as trust grows\nShort loans cost more than savings earn, in Bizzington as in most places — the bank keeps the difference. The total is always shown before you agree.","route":"#/sources/loan","cta":"How we know","source":"How we know","id":"f-figure-loan","bands":["sprout","builder"],"maths":"M10","because":"A number Chapter 6 · Borrowing runs on, and how we know it","grp":"figure:loan"},"f-figure-climb":{"kind":"figure","src":"figure:climb","level":6,"topics":["figure","ch:c6"],"badge":{"id":"own","label":"A dial of this town"},"title":"Compound Climb's growth","body":"about 11 in every 100 a year at a steady charge\nA dial of this town, for a game: your stall's and jobs' Bizzington, never a household's, a real shop or a market's record.","route":"#/sources/climb","cta":"How we know","source":"How we know","id":"f-figure-climb","bands":["sprout","builder"],"maths":"M11","because":"A number Chapter 6 · Borrowing runs on, and how we know it","grp":"figure:climb"},"f-game-cc":{"kind":"game","src":"game:cc","level":6,"topics":["game","game:cc","ch:c6"],"gate":{"chapter":"c6"},"title":"Compound Climb","body":"Hold to grow the tower. Hold longer for more — and past a point it can go backwards, and you can be wiped out.\nhow compounding grows, how to estimate it — and why greed crashes it","route":"#/play/cc","cta":"Go and play","source":"Play · keys hold space · ↑↓ ⏎ · opens with Chapter 6 · Borrowing","id":"f-game-cc","bands":["sprout","builder"],"maths":"M11","grp":"game:cc"},"f-badge-chapter-c6":{"kind":"medal","src":"badge:chapter-c6","level":6,"topics":["medal","ch:c6"],"badgeId":"chapter-c6","title":"Borrowing","body":"Chapter six, done.","route":"#/medals/chapter-c6","cta":"How to earn it","source":"Medal · for finishing Chapter 6 · Borrowing","id":"f-badge-chapter-c6","bands":["sprout","builder"],"maths":"M1","because":"A medal you have not earned yet","grp":"badge:chapter-c6"},"f-assess-choose-8-0":{"kind":"question","src":"assess:CHOOSE-8#0","level":6,"topics":["card:x-ch8","ch:c6","goal:CHOOSE-8","who:nana"],"key":"CHOOSE-8#0#0","title":"Weighing waiting against buying now","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","play":{"q":"You save 120 a week and the thing is 500. How many weeks?","opts":["Five, with 100 spare","Four, with 20 short","Six","Four"],"after":"120 × 4 = 480, which is 20 short — so five weeks, and you are 100 over. Division with a remainder is exactly what saving up is."},"source":"Chapter 6 · Borrowing · a question to come back to","id":"f-assess-choose-8-0","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-assess-choose-8-0why":{"kind":"why","src":"assess:CHOOSE-8#0why","level":6,"topics":["card:x-ch8","ch:c6","goal:CHOOSE-8","who:nana"],"card":"x-ch8","title":"Weighing waiting against buying now","body":"120 × 4 = 480, which is 20 short — so five weeks, and you are 100 over. Division with a remainder is exactly what saving up is.","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · why, said again","id":"f-assess-choose-8-0why","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-assess-choose-8-1":{"kind":"question","src":"assess:CHOOSE-8#1","level":6,"topics":["card:x-ch8","ch:c6","goal:CHOOSE-8","who:nana"],"key":"CHOOSE-8#1#0","title":"Weighing waiting against buying now","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","play":{"q":"What makes buying now the better answer sometimes?","opts":["When having it sooner is worth more to you than the extra it costs","When you can afford the payments","Never — always wait","When it is on offer"],"after":"Waiting is not a virtue and buying now is not a failure. It is a comparison, and the honest answer needs both columns written down."},"source":"Chapter 6 · Borrowing · a question to come back to","id":"f-assess-choose-8-1","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-assess-choose-8-1why":{"kind":"why","src":"assess:CHOOSE-8#1why","level":6,"topics":["card:x-ch8","ch:c6","goal:CHOOSE-8","who:nana"],"card":"x-ch8","title":"Weighing waiting against buying now","body":"Waiting is not a virtue and buying now is not a failure. It is a comparison, and the honest answer needs both columns written down.","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · why, said again","id":"f-assess-choose-8-1why","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-assess-choose-8-2":{"kind":"question","src":"assess:CHOOSE-8#2","level":6,"topics":["card:x-ch8","ch:c6","goal:CHOOSE-8","who:nana"],"key":"CHOOSE-8#2#0","title":"Weighing waiting against buying now","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","play":{"q":"The thing costs 800 now or 800 in three weeks, and borrowing adds 80. What are you buying for 80?","opts":["Three weeks of having it","The shop’s trust","A better version","Nothing"],"after":"Naming what the 80 buys turns a vague feeling into a straight question: are three weeks worth 80 to me, right now?"},"source":"Chapter 6 · Borrowing · a question to come back to","id":"f-assess-choose-8-2","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-assess-choose-8-2why":{"kind":"why","src":"assess:CHOOSE-8#2why","level":6,"topics":["card:x-ch8","ch:c6","goal:CHOOSE-8","who:nana"],"card":"x-ch8","title":"Weighing waiting against buying now","body":"Naming what the 80 buys turns a vague feeling into a straight question: are three weeks worth 80 to me, right now?","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · why, said again","id":"f-assess-choose-8-2why","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-assess-grow-2-0":{"kind":"question","src":"assess:GROW-2#0","level":6,"topics":["card:c6a","ch:c6","goal:GROW-2","who:nana"],"key":"GROW-2#0#0","title":"Interest, in coins","route":"#/atlas/c6a","cta":"Open the lesson","maths":"M10","play":{"q":"500 in the bank at 2% a period. What lands?","opts":["10","2","20","50"],"after":"Two in every hundred, and there are five hundreds — so 10. Saying it in coins is what stops a percent hiding the size."},"source":"Chapter 6 · Borrowing · a question to come back to","id":"f-assess-grow-2-0","bands":["sprout","builder"],"grp":"card:c6a"},"f-assess-grow-2-0why":{"kind":"why","src":"assess:GROW-2#0why","level":6,"topics":["card:c6a","ch:c6","goal:GROW-2","who:nana"],"card":"c6a","title":"Interest, in coins","body":"Two in every hundred, and there are five hundreds — so 10. Saying it in coins is what stops a percent hiding the size.","route":"#/atlas/c6a","cta":"Open the lesson","maths":"M10","source":"Chapter 6 · Borrowing · why, said again","id":"f-assess-grow-2-0why","bands":["sprout","builder"],"grp":"card:c6a"},"f-assess-grow-2-2":{"kind":"question","src":"assess:GROW-2#2","level":6,"topics":["card:c6a","ch:c6","goal:GROW-2","who:nana"],"key":"GROW-2#2#0","title":"Interest, in coins","route":"#/atlas/c6a","cta":"Open the lesson","maths":"M10","play":{"q":"Which pays more: 5% on 200 or 2% on 1,000?","opts":["2% on 1,000","Cannot compare","The same","5% on 200"],"after":"10 against 20. The bigger rate on the smaller pile lost, which is why you turn both into coins before deciding."},"source":"Chapter 6 · Borrowing · a question to come back to","id":"f-assess-grow-2-2","bands":["sprout","builder"],"grp":"card:c6a"},"f-assess-grow-2-2why":{"kind":"why","src":"assess:GROW-2#2why","level":6,"topics":["card:c6a","ch:c6","goal:GROW-2","who:nana"],"card":"c6a","title":"Interest, in coins","body":"10 against 20. The bigger rate on the smaller pile lost, which is why you turn both into coins before deciding.","route":"#/atlas/c6a","cta":"Open the lesson","maths":"M10","source":"Chapter 6 · Borrowing · why, said again","id":"f-assess-grow-2-2why","bands":["sprout","builder"],"grp":"card:c6a"},"f-assess-owe-1-0":{"kind":"question","src":"assess:OWE-1#0","level":6,"topics":["card:c6a","ch:c6","goal:OWE-1","who:nana"],"key":"OWE-1#0#0","title":"Borrowing","route":"#/atlas/c6a","cta":"Open the lesson","maths":"M10","play":{"q":"You borrow 500 and pay back 560. What was the 60?","opts":["The price of having the money sooner","A mistake","A fine","A gift to the bank"],"after":"You rented money for a while. 60 is the rent, and it bought you the time between then and now."},"source":"Chapter 6 · Borrowing · a question to come back to","id":"f-assess-owe-1-0","bands":["sprout","builder"],"grp":"card:c6a"},"f-assess-owe-1-0why":{"kind":"why","src":"assess:OWE-1#0why","level":6,"topics":["card:c6a","ch:c6","goal:OWE-1","who:nana"],"card":"c6a","title":"Borrowing has a price","body":"You rented money for a while. 60 is the rent, and it bought you the time between then and now.","route":"#/atlas/c6a","cta":"Open the lesson","maths":"M10","source":"Chapter 6 · Borrowing · why, said again","id":"f-assess-owe-1-0why","bands":["sprout","builder"],"grp":"card:c6a"},"f-assess-owe-1-2":{"kind":"question","src":"assess:OWE-1#2","level":6,"topics":["card:c6a","ch:c6","goal:OWE-1","who:nana"],"key":"OWE-1#2#0","title":"Borrowing","route":"#/atlas/c6a","cta":"Open the lesson","maths":"M10","play":{"q":"Somebody says a loan is \"interest free\". What should you check?","opts":["What else it costs — a fee, a higher price, a penalty later","The bank's name","The colour of the form","Nothing, that is good news"],"after":"Money is not usually lent for nothing. If the interest is not the price, look for where the price went."},"source":"Chapter 6 · Borrowing · a question to come back to","id":"f-assess-owe-1-2","bands":["sprout","builder"],"grp":"card:c6a"},"f-assess-owe-1-2why":{"kind":"why","src":"assess:OWE-1#2why","level":6,"topics":["card:c6a","ch:c6","goal:OWE-1","who:nana"],"card":"c6a","title":"Borrowing has a price","body":"Money is not usually lent for nothing. If the interest is not the price, look for where the price went.","route":"#/atlas/c6a","cta":"Open the lesson","maths":"M10","source":"Chapter 6 · Borrowing · why, said again","id":"f-assess-owe-1-2why","bands":["sprout","builder"],"grp":"card:c6a"},"f-assess-owe-2-0":{"kind":"question","src":"assess:OWE-2#0","level":6,"topics":["card:c6b","ch:c6","goal:OWE-2","who:pip"],"key":"OWE-2#0#0","title":"The number that matters","route":"#/atlas/c6b","cta":"Open the lesson","maths":"M9","play":{"q":"\"Only 40 a week for 24 weeks.\" What are you agreeing to?","opts":["960","40","240","It does not say"],"after":"40 × 24 = 960. The small number is the one you are shown; the big one is the one you are agreeing to."},"source":"Chapter 6 · Borrowing · a question to come back to","id":"f-assess-owe-2-0","bands":["sprout","builder"],"grp":"card:c6b"},"f-assess-owe-2-0why":{"kind":"why","src":"assess:OWE-2#0why","level":6,"topics":["card:c6b","ch:c6","goal:OWE-2","who:pip"],"card":"c6b","title":"The number that matters","body":"40 × 24 = 960. The small number is the one you are shown; the big one is the one you are agreeing to.","route":"#/atlas/c6b","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · why, said again","id":"f-assess-owe-2-0why","bands":["sprout","builder"],"grp":"card:c6b"},"f-assess-owe-2-1":{"kind":"question","src":"assess:OWE-2#1","level":6,"topics":["card:c6b","ch:c6","goal:OWE-2","who:pip"],"key":"OWE-2#1#0","title":"Borrowing","route":"#/atlas/c6b","cta":"Open the lesson","maths":"M9","play":{"q":"Why do offers advertise the weekly payment?","opts":["Because it is the smallest true number they can show you","It is more honest","To help you budget","It is easier to calculate"],"after":"Every part of it is true, and the total is still the thing you need. It is not a lie; it is a choice about which truth to show."},"source":"Chapter 6 · Borrowing · a question to come back to","id":"f-assess-owe-2-1","bands":["sprout","builder"],"grp":"card:c6b"},"f-assess-owe-2-1why":{"kind":"why","src":"assess:OWE-2#1why","level":6,"topics":["card:c6b","ch:c6","goal:OWE-2","who:pip"],"card":"c6b","title":"The number that matters","body":"Every part of it is true, and the total is still the thing you need. It is not a lie; it is a choice about which truth to show.","route":"#/atlas/c6b","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · why, said again","id":"f-assess-owe-2-1why","bands":["sprout","builder"],"grp":"card:c6b"},"f-assess-owe-2-2":{"kind":"question","src":"assess:OWE-2#2","level":6,"topics":["card:c6b","ch:c6","goal:OWE-2","who:pip"],"key":"OWE-2#2#0","title":"The number that matters","route":"#/atlas/c6b","cta":"Open the lesson","maths":"M9","play":{"q":"Two loans for the same thing. One is 30 a week for 40 weeks, one is 50 for 22. Which costs less?","opts":["The 50 one — 1,100 against 1,200","The one with the lower weekly","The 30 one","The same"],"after":"The smaller weekly payment cost 100 more in the end. That gap is where the whole trick lives."},"source":"Chapter 6 · Borrowing · a question to come back to","id":"f-assess-owe-2-2","bands":["sprout","builder"],"grp":"card:c6b"},"f-assess-owe-2-2why":{"kind":"why","src":"assess:OWE-2#2why","level":6,"topics":["card:c6b","ch:c6","goal:OWE-2","who:pip"],"card":"c6b","title":"The number that matters","body":"The smaller weekly payment cost 100 more in the end. That gap is where the whole trick lives.","route":"#/atlas/c6b","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · why, said again","id":"f-assess-owe-2-2why","bands":["sprout","builder"],"grp":"card:c6b"},"f-assess-owe-3-1":{"kind":"question","src":"assess:OWE-3#1","level":6,"topics":["card:c6c","ch:c6","goal:OWE-3","who:nana"],"key":"OWE-3#1#0","title":"Good reasons and bad ones","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","play":{"q":"Borrowing for something that is gone by the time you finish paying — what is wrong with it?","opts":["You keep paying for something you no longer have","It is against the rules","It costs more","Nothing"],"after":"The payments outlive the thing. That is not a moral failing; it is just the worst shape a deal can have."},"source":"Chapter 6 · Borrowing · a question to come back to","id":"f-assess-owe-3-1","bands":["sprout","builder"],"grp":"card:c6c"},"f-assess-owe-3-1why":{"kind":"why","src":"assess:OWE-3#1why","level":6,"topics":["card:c6c","ch:c6","goal:OWE-3","who:nana"],"card":"c6c","title":"Good reasons and bad ones","body":"The payments outlive the thing. That is not a moral failing; it is just the worst shape a deal can have.","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","source":"Chapter 6 · Borrowing · why, said again","id":"f-assess-owe-3-1why","bands":["sprout","builder"],"grp":"card:c6c"},"f-assess-owe-3-2":{"kind":"question","src":"assess:OWE-3#2","level":6,"topics":["card:c6c","ch:c6","goal:OWE-3","who:nana"],"key":"OWE-3#2#0","title":"Good reasons and bad ones","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","play":{"q":"Is \"everybody borrows for this\" a reason?","opts":["No — it tells you nothing about your own numbers","Yes","Only for houses","Only for small amounts"],"after":"What other people do is information about other people. Your own total, and what it buys you, is the only reason that holds."},"source":"Chapter 6 · Borrowing · a question to come back to","id":"f-assess-owe-3-2","bands":["sprout","builder"],"grp":"card:c6c"},"f-assess-owe-3-2why":{"kind":"why","src":"assess:OWE-3#2why","level":6,"topics":["card:c6c","ch:c6","goal:OWE-3","who:nana"],"card":"c6c","title":"Good reasons and bad ones","body":"What other people do is information about other people. Your own total, and what it buys you, is the only reason that holds.","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","source":"Chapter 6 · Borrowing · why, said again","id":"f-assess-owe-3-2why","bands":["sprout","builder"],"grp":"card:c6c"},"f-gen-owe-3-1":{"kind":"question","src":"gen:OWE-3~1","level":6,"topics":["card:c6c","ch:c6","goal:OWE-3","who:nana"],"key":"OWE-3~1#0","title":"Good reasons and bad ones","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","play":{"q":"Pip says, “Borrow — it is only {c3} a week!” What should Nana Bizz look at instead?","opts":["The total cost of the loan and what it is for","The colour of the form","What Pip would do","Only the weekly amount"],"after":"A small weekly payment can hide a big total. The reason and the total decide whether it is worth it."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-3-1","bands":["sprout","builder"],"grp":"card:c6c"},"f-gen-owe-3-1-why":{"kind":"why","src":"gen:OWE-3~1#why","level":6,"topics":["card:c6c","ch:c6","goal:OWE-3","who:nana"],"card":"c6c","title":"Good reasons and bad ones","body":"A small weekly payment can hide a big total. The reason and the total decide whether it is worth it.","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","source":"Chapter 6 · Borrowing · why, said again","id":"f-gen-owe-3-1-why","bands":["sprout","builder"],"grp":"card:c6c"},"f-gen-owe-3-2":{"kind":"question","src":"gen:OWE-3~2","level":6,"topics":["card:c6c","ch:c6","goal:OWE-3","who:nana"],"key":"OWE-3~2#0","title":"Good reasons and bad ones","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","play":{"q":"Bea could borrow {c10} for a ladder for window cleaning, paying back {c12}. While the loan runs, a ladder for window cleaning would earn {c3}. Is that a good reason to borrow?","opts":["Yes — it earns {c3}, more than the {c2} it costs","No — borrowing is always a bad idea","Yes — borrowing for work always pays","Only if the ladder for window cleaning is brand new"],"after":"The loan costs {c12} − {c10} = {c2}. Set that against the {c3} it earns. Borrowing is a tool with a price — the numbers decide, not a rule."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-3-2","bands":["sprout","builder"],"grp":"card:c6c"},"f-gen-owe-3-2-why":{"kind":"why","src":"gen:OWE-3~2#why","level":6,"topics":["card:c6c","ch:c6","goal:OWE-3","who:nana"],"card":"c6c","title":"Good reasons and bad ones","body":"The loan costs {c12} − {c10} = {c2}. Set that against the {c3} it earns. Borrowing is a tool with a price — the numbers decide, not a rule.","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","source":"Chapter 6 · Borrowing · why, said again","id":"f-gen-owe-3-2-why","bands":["sprout","builder"],"grp":"card:c6c"},"f-gen-owe-3-3":{"kind":"question","src":"gen:OWE-3~3","level":6,"topics":["card:c6c","ch:c6","goal:OWE-3","who:nana"],"key":"OWE-3~3#0","title":"Good reasons and bad ones","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","play":{"q":"Nana Bizz borrows for a big ice-cream party and pays it back over 4 weeks. What is the catch?","opts":["Nana Bizz is still paying after the fun is over","Borrowing is against the rules","Nana Bizz pays back less than was borrowed","There is no catch"],"after":"The fun lasts a day; the payments last 4 weeks. That is worth knowing before, not after — it is a price, not a punishment."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-3-3","bands":["sprout","builder"],"grp":"card:c6c"},"f-gen-owe-3-3-why":{"kind":"why","src":"gen:OWE-3~3#why","level":6,"topics":["card:c6c","ch:c6","goal:OWE-3","who:nana"],"card":"c6c","title":"Good reasons and bad ones","body":"The fun lasts a day; the payments last 4 weeks. That is worth knowing before, not after — it is a price, not a punishment.","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","source":"Chapter 6 · Borrowing · why, said again","id":"f-gen-owe-3-3-why","bands":["sprout","builder"],"grp":"card:c6c"},"f-gen-owe-3-4":{"kind":"question","src":"gen:OWE-3~4","level":6,"topics":["card:c6c","ch:c6","goal:OWE-3","who:nana"],"key":"OWE-3~4#0","title":"Good reasons and bad ones","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","play":{"q":"Mags borrows to buy fabric in bulk before the monsoon, when umbrellas sell fast. Is that a sensible reason?","opts":["Yes, if the extra sales cover the loan’s price","Only if the fabric is red","Yes, always","No, never borrow for a business"],"after":"Borrowing to meet a known busy season can pay. The sum still has to work: extra sales minus the loan’s price."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-3-4","bands":["sprout","builder"],"grp":"card:c6c"},"f-gen-owe-3-4-why":{"kind":"why","src":"gen:OWE-3~4#why","level":6,"topics":["card:c6c","ch:c6","goal:OWE-3","who:nana"],"card":"c6c","title":"Good reasons and bad ones","body":"Borrowing to meet a known busy season can pay. The sum still has to work: extra sales minus the loan’s price.","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","source":"Chapter 6 · Borrowing · why, said again","id":"f-gen-owe-3-4-why","bands":["sprout","builder"],"grp":"card:c6c"},"f-gen-owe-3-8":{"kind":"question","src":"gen:OWE-3~8","level":6,"topics":["card:c6c","ch:c6","goal:OWE-3","who:nana"],"key":"OWE-3~8#0","title":"Good reasons and bad ones","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","play":{"q":"Bo wants to borrow for a new game console because it is on offer. What is the honest question?","opts":["Would the offer still be worth it after the loan’s price is added?","How many games does it have?","Is the offer real?","Will friends be jealous?"],"after":"A discount can disappear inside a loan’s price. Add the cost of borrowing before calling it a bargain."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-3-8","bands":["sprout","builder"],"grp":"card:c6c"},"f-gen-owe-3-8-why":{"kind":"why","src":"gen:OWE-3~8#why","level":6,"topics":["card:c6c","ch:c6","goal:OWE-3","who:nana"],"card":"c6c","title":"Good reasons and bad ones","body":"A discount can disappear inside a loan’s price. Add the cost of borrowing before calling it a bargain.","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","source":"Chapter 6 · Borrowing · why, said again","id":"f-gen-owe-3-8-why","bands":["sprout","builder"],"grp":"card:c6c"},"f-gen-owe-3-9":{"kind":"question","src":"gen:OWE-3~9","level":6,"topics":["card:c6c","ch:c6","goal:OWE-3","who:nana"],"key":"OWE-3~9#0","title":"Good reasons and bad ones","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","play":{"q":"Bea could borrow to buy a fishing net that would let Bea sell fish every morning at the harbour. What makes this a good reason to borrow?","opts":["The net could earn more than the loan costs","Borrowing is always good","Everyone borrows for nets","Nets are pretty"],"after":"A loan for a tool that earns can pay for itself. The question is always whether it earns more than the price of borrowing."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-3-9","bands":["sprout","builder"],"grp":"card:c6c"},"f-gen-owe-3-9-why":{"kind":"why","src":"gen:OWE-3~9#why","level":6,"topics":["card:c6c","ch:c6","goal:OWE-3","who:nana"],"card":"c6c","title":"Good reasons and bad ones","body":"A loan for a tool that earns can pay for itself. The question is always whether it earns more than the price of borrowing.","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","source":"Chapter 6 · Borrowing · why, said again","id":"f-gen-owe-3-9-why","bands":["sprout","builder"],"grp":"card:c6c"},"f-gen-owe-3-10":{"kind":"question","src":"gen:OWE-3~10","level":6,"topics":["card:c6c","ch:c6","goal:OWE-3","who:nana"],"key":"OWE-3~10#0","title":"Good reasons and bad ones","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","play":{"q":"Which is the better reason for Bo to borrow?","opts":["For a sewing kit to mend and sell bags, earning more than the loan costs","For sweets for the weekend","For a game because everybody has it","For a treat to have today"],"after":"A loan has a price. Borrowing for something that earns more than that price can pay for itself; borrowing for something that is soon gone cannot."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-3-10","bands":["sprout","builder"],"grp":"card:c6c"},"f-gen-owe-3-10-why":{"kind":"why","src":"gen:OWE-3~10#why","level":6,"topics":["card:c6c","ch:c6","goal:OWE-3","who:nana"],"card":"c6c","title":"Good reasons and bad ones","body":"A loan has a price. Borrowing for something that earns more than that price can pay for itself; borrowing for something that is soon gone cannot.","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","source":"Chapter 6 · Borrowing · why, said again","id":"f-gen-owe-3-10-why","bands":["sprout","builder"],"grp":"card:c6c"},"f-gen-owe-3-11":{"kind":"question","src":"gen:OWE-3~11","level":6,"topics":["card:c6c","ch:c6","goal:OWE-3","who:nana"],"key":"OWE-3~11#0","title":"Good reasons and bad ones","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","play":{"q":"Pip could borrow {c30} for a juice press, paying back {c33}. While the loan runs, a juice press would earn {c5}. Is that a good reason to borrow?","opts":["Yes — it earns {c5}, more than the {c3} it costs","Yes — borrowing for work always pays","No — borrowing is always a bad idea","Only if the juice press is brand new"],"after":"The loan costs {c33} − {c30} = {c3}. Set that against the {c5} it earns. Borrowing is a tool with a price — the numbers decide, not a rule."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-3-11","bands":["sprout","builder"],"grp":"card:c6c"},"f-gen-owe-3-14":{"kind":"question","src":"gen:OWE-3~14","level":6,"topics":["card:c6c","ch:c6","goal:OWE-3","who:nana"],"key":"OWE-3~14#0","title":"Good reasons and bad ones","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","play":{"q":"Bo could borrow {c30} for a sewing kit, paying back {c31}. While the loan runs, a sewing kit would earn {c2}. Is that a good reason to borrow?","opts":["Yes — it earns {c2}, more than the {c1} it costs","Yes — borrowing for work always pays","No — borrowing is always a bad idea","Only if the sewing kit is brand new"],"after":"The loan costs {c31} − {c30} = {c1}. Set that against the {c2} it earns. Borrowing is a tool with a price — the numbers decide, not a rule."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-3-14","bands":["sprout","builder"],"grp":"card:c6c"},"f-gen-owe-3-15":{"kind":"question","src":"gen:OWE-3~15","level":6,"topics":["card:c6c","ch:c6","goal:OWE-3","who:nana"],"key":"OWE-3~15#0","title":"Good reasons and bad ones","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","play":{"q":"Bea’s bicycle breaks and Bea needs it for the delivery round on Monday. Is borrowing to fix it a reasonable choice?","opts":["Yes — without it Bea cannot earn, and the round pays more than the loan costs","No, it is never reasonable","Only if the bike is new","Only for a new bicycle"],"after":"Borrowing to keep your income going can be a good use of credit. Check that the work pays more than the price of the loan."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-3-15","bands":["sprout","builder"],"grp":"card:c6c"},"f-gen-owe-3-15-why":{"kind":"why","src":"gen:OWE-3~15#why","level":6,"topics":["card:c6c","ch:c6","goal:OWE-3","who:nana"],"card":"c6c","title":"Good reasons and bad ones","body":"Borrowing to keep your income going can be a good use of credit. Check that the work pays more than the price of the loan.","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","source":"Chapter 6 · Borrowing · why, said again","id":"f-gen-owe-3-15-why","bands":["sprout","builder"],"grp":"card:c6c"},"f-gen-owe-3-19":{"kind":"question","src":"gen:OWE-3~19","level":6,"topics":["card:c6c","ch:c6","goal:OWE-3","who:nana"],"key":"OWE-3~19#0","title":"Good reasons and bad ones","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","play":{"q":"Bo borrows for a pile of party balloons and pays it back over 8 weeks. What is the catch?","opts":["Bo is still paying after the fun is over","Borrowing is against the rules","Bo pays back less than was borrowed","There is no catch"],"after":"The fun lasts a day; the payments last 8 weeks. That is worth knowing before, not after — it is a price, not a punishment."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-3-19","bands":["sprout","builder"],"grp":"card:c6c"},"f-gen-owe-3-23":{"kind":"question","src":"gen:OWE-3~23","level":6,"topics":["card:c6c","ch:c6","goal:OWE-3","who:nana"],"key":"OWE-3~23#0","title":"Good reasons and bad ones","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","play":{"q":"Bo wants to borrow for a party that lasts one evening, paying back for two months. What is worth noticing?","opts":["The payments last much longer than the fun","Borrowing is forbidden","Parties are bad","Nothing"],"after":"It is not wrong — it is a price. Two months of payments for one evening is worth knowing before saying yes."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-3-23","bands":["sprout","builder"],"grp":"card:c6c"},"f-gen-owe-3-23-why":{"kind":"why","src":"gen:OWE-3~23#why","level":6,"topics":["card:c6c","ch:c6","goal:OWE-3","who:nana"],"card":"c6c","title":"Good reasons and bad ones","body":"It is not wrong — it is a price. Two months of payments for one evening is worth knowing before saying yes.","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","source":"Chapter 6 · Borrowing · why, said again","id":"f-gen-owe-3-23-why","bands":["sprout","builder"],"grp":"card:c6c"},"f-gen-owe-3-30":{"kind":"question","src":"gen:OWE-3~30","level":6,"topics":["card:c6c","ch:c6","goal:OWE-3","who:nana"],"key":"OWE-3~30#0","title":"Good reasons and bad ones","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","play":{"q":"Mags borrows for a day at the water park and pays it back over 4 weeks. What is the catch?","opts":["Mags is still paying after the fun is over","There is no catch","Mags pays back less than was borrowed","Borrowing is against the rules"],"after":"The fun lasts a day; the payments last 4 weeks. That is worth knowing before, not after — it is a price, not a punishment."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-3-30","bands":["sprout","builder"],"grp":"card:c6c"},"f-assess-owe-4-0":{"kind":"question","src":"assess:OWE-4#0","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"key":"OWE-4#0#0","title":"Paying it when you would rather not","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"A repayment is due and you want something else. What is the honest way to see it?","opts":["The thing you want costs the repayment plus its own price","The repayment is unfair","Skip it this once","The money is not really yours"],"after":"You already spent this money when you borrowed. Today is just when it leaves — and anything else you buy is on top of that."},"source":"Chapter 6 · Borrowing · a question to come back to","id":"f-assess-owe-4-0","bands":["sprout","builder"],"grp":"card:c6d"},"f-assess-owe-4-0why":{"kind":"why","src":"assess:OWE-4#0why","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"card":"c6d","title":"Paying it when you would rather not","body":"You already spent this money when you borrowed. Today is just when it leaves — and anything else you buy is on top of that.","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","source":"Chapter 6 · Borrowing · why, said again","id":"f-assess-owe-4-0why","bands":["sprout","builder"],"grp":"card:c6d"},"f-assess-owe-4-1":{"kind":"question","src":"assess:OWE-4#1","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"key":"OWE-4#1#0","title":"Paying it when you would rather not","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"What happens when a repayment is missed?","opts":["It usually costs more, and it is remembered","Nothing","It disappears","It moves to next year"],"after":"Missing costs twice: a charge now and a smaller offer next time. Neither is punishment; both are the lender pricing what they saw."},"source":"Chapter 6 · Borrowing · a question to come back to","id":"f-assess-owe-4-1","bands":["sprout","builder"],"grp":"card:c6d"},"f-assess-owe-4-1why":{"kind":"why","src":"assess:OWE-4#1why","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"card":"c6d","title":"Paying it when you would rather not","body":"Missing costs twice: a charge now and a smaller offer next time. Neither is punishment; both are the lender pricing what they saw.","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","source":"Chapter 6 · Borrowing · why, said again","id":"f-assess-owe-4-1why","bands":["sprout","builder"],"grp":"card:c6d"},"f-assess-owe-4-2":{"kind":"question","src":"assess:OWE-4#2","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"key":"OWE-4#2#0","title":"Paying it when you would rather not","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"You cannot make a payment. What is the strong move?","opts":["Tell them before it is due","Pay half quietly","Borrow from somewhere else","Say nothing and hope"],"after":"Told early, it is usually a conversation. Discovered late, it is a problem — and that difference is entirely in the telling."},"source":"Chapter 6 · Borrowing · a question to come back to","id":"f-assess-owe-4-2","bands":["sprout","builder"],"grp":"card:c6d"},"f-assess-owe-4-2why":{"kind":"why","src":"assess:OWE-4#2why","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"card":"c6d","title":"Paying it when you would rather not","body":"Told early, it is usually a conversation. Discovered late, it is a problem — and that difference is entirely in the telling.","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","source":"Chapter 6 · Borrowing · why, said again","id":"f-assess-owe-4-2why","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-4-1":{"kind":"question","src":"gen:OWE-4~1","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"key":"OWE-4~1#0","title":"Paying it when you would rather not","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"Mags must repay the bank this week, and a customer offers a big order if she buys extra stock first. What is her honest choice?","opts":["Weigh the order against breaking the repayment promise","Borrow from the customer","Ignore the repayment","Always skip the order"],"after":"Some weeks have two good things competing. Naming both — the order and the promise — is how she chooses well."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-4-1","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-4-1-why":{"kind":"why","src":"gen:OWE-4~1#why","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"card":"c6d","title":"Paying it when you would rather not","body":"Some weeks have two good things competing. Naming both — the order and the promise — is how she chooses well.","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","source":"Chapter 6 · Borrowing · why, said again","id":"f-gen-owe-4-1-why","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-4-3":{"kind":"question","src":"gen:OWE-4~3","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"key":"OWE-4~3#0","title":"Paying it when you would rather not","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"What usually happens when Nana Bizz misses a repayment to the lending desk at the bank?","opts":["It costs more, and it is remembered","It quietly moves to next year","Nothing at all","The loan disappears"],"after":"A missed payment usually adds a charge, and lenders remember. Both make the next loan dearer."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-4-3","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-4-3-why":{"kind":"why","src":"gen:OWE-4~3#why","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"card":"c6d","title":"Paying it when you would rather not","body":"A missed payment usually adds a charge, and lenders remember. Both make the next loan dearer.","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","source":"Chapter 6 · Borrowing · why, said again","id":"f-gen-owe-4-3-why","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-4-6":{"kind":"question","src":"gen:OWE-4~6","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"key":"OWE-4~6#0","title":"Paying it when you would rather not","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"A repayment of {c4} to the lending desk at the bank is due, and Bo wants a bicycle bell for {c6}. What is the honest way to see it?","opts":["Its real cost is {c6} plus a broken promise","The repayment is unfair","The money is not really Bo’s","Skip it once; nobody minds"],"after":"A repayment is a promise already made. Spending its money means paying for the thing and for breaking the promise."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-4-6","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-4-6-why":{"kind":"why","src":"gen:OWE-4~6#why","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"card":"c6d","title":"Paying it when you would rather not","body":"A repayment is a promise already made. Spending its money means paying for the thing and for breaking the promise.","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","source":"Chapter 6 · Borrowing · why, said again","id":"f-gen-owe-4-6-why","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-4-8":{"kind":"question","src":"gen:OWE-4~8","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"key":"OWE-4~8#0","title":"Paying it when you would rather not","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"Why does missing a repayment usually cost more than the payment itself?","opts":["There may be a charge, and the lender trusts Pip less next time","The bank doubles everything","It does not cost more","The loan ends"],"after":"A missed payment adds costs now and later. That is why keeping it, even when hard, usually pays."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-4-8","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-4-8-why":{"kind":"why","src":"gen:OWE-4~8#why","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"card":"c6d","title":"Paying it when you would rather not","body":"A missed payment adds costs now and later. That is why keeping it, even when hard, usually pays.","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","source":"Chapter 6 · Borrowing · why, said again","id":"f-gen-owe-4-8-why","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-4-9":{"kind":"question","src":"gen:OWE-4~9","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"key":"OWE-4~9#0","title":"Paying it when you would rather not","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"Bea owes Bo {c6} on Friday, and on Thursday a comic Bea loves comes out. What makes Friday easier?","opts":["Setting the repayment aside on payday, before shopping","Asking Bo to forget it","Paying half without saying","Buying the comic and hoping"],"after":"Putting the repayment aside first turns it into money that is already spoken for."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-4-9","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-4-9-why":{"kind":"why","src":"gen:OWE-4~9#why","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"card":"c6d","title":"Paying it when you would rather not","body":"Putting the repayment aside first turns it into money that is already spoken for.","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","source":"Chapter 6 · Borrowing · why, said again","id":"f-gen-owe-4-9-why","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-4-12":{"kind":"question","src":"gen:OWE-4~12","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"key":"OWE-4~12#0","title":"Paying it when you would rather not","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"A repayment of {c2} to the Bizzington bank is due, and Mags wants a paint set for {c5}. What is the honest way to see it?","opts":["Its real cost is {c5} plus a broken promise","The repayment is unfair","Skip it once; nobody minds","The money is not really Mags’s"],"after":"A repayment is a promise already made. Spending its money means paying for the thing and for breaking the promise."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-4-12","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-4-13":{"kind":"question","src":"gen:OWE-4~13","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"key":"OWE-4~13#0","title":"Paying it when you would rather not","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"Pip pays Mags the {c6} instead of buying a kite. What did Pip give up?","opts":["Having it this week","Nothing — repayments do not count","{c6} for nothing","The loan itself"],"after":"Keeping a repayment has a cost too, and naming it is honest. What you get back is a kept promise and a cheaper next loan."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-4-13","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-4-13-why":{"kind":"why","src":"gen:OWE-4~13#why","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"card":"c6d","title":"Paying it when you would rather not","body":"Keeping a repayment has a cost too, and naming it is honest. What you get back is a kept promise and a cheaper next loan.","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","source":"Chapter 6 · Borrowing · why, said again","id":"f-gen-owe-4-13-why","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-4-15":{"kind":"question","src":"gen:OWE-4~15","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"key":"OWE-4~15#0","title":"Paying it when you would rather not","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"Bea cannot pay the full amount this week. What is the strong thing to do?","opts":["Tell the lender early and agree a new plan","Borrow somewhere else quietly","Stay silent and hope","Pay nothing and hide"],"after":"Lenders can often help when told in time. Silence turns a problem into a broken promise."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-4-15","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-4-15-why":{"kind":"why","src":"gen:OWE-4~15#why","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"card":"c6d","title":"Paying it when you would rather not","body":"Lenders can often help when told in time. Silence turns a problem into a broken promise.","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","source":"Chapter 6 · Borrowing · why, said again","id":"f-gen-owe-4-15-why","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-4-23":{"kind":"question","src":"gen:OWE-4~23","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"key":"OWE-4~23#0","title":"Paying it when you would rather not","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"Bo repaid the bank on time even though it meant skipping the fair. What did Bo get for it?","opts":["A kept promise and a better name with the bank","A bigger loan right away","A free ticket to the fair","Nothing"],"after":"A kept repayment is invisible on the day and valuable later: the next loan is easier and cheaper."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-4-23","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-4-23-why":{"kind":"why","src":"gen:OWE-4~23#why","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"card":"c6d","title":"Paying it when you would rather not","body":"A kept repayment is invisible on the day and valuable later: the next loan is easier and cheaper.","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","source":"Chapter 6 · Borrowing · why, said again","id":"f-gen-owe-4-23-why","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-4-24":{"kind":"question","src":"gen:OWE-4~24","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"key":"OWE-4~24#0","title":"Paying it when you would rather not","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"Bea pays Mags the {c4} instead of buying a paint set. What did Bea give up?","opts":["Having it this week","{c4} for nothing","Nothing — repayments do not count","The loan itself"],"after":"Keeping a repayment has a cost too, and naming it is honest. What you get back is a kept promise and a cheaper next loan."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-4-24","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-4-28":{"kind":"question","src":"gen:OWE-4~28","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"key":"OWE-4~28#0","title":"Paying it when you would rather not","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"A repayment of {c6} to Nana Bizz is due, and Bea wants a paint set for {c9}. What is the honest way to see it?","opts":["Its real cost is {c9} plus a broken promise","The money is not really Bea’s","Skip it once; nobody minds","The repayment is unfair"],"after":"A repayment is a promise already made. Spending its money means paying for the thing and for breaking the promise."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-4-28","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-4-59":{"kind":"question","src":"gen:OWE-4~59","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"key":"OWE-4~59#0","title":"Paying it when you would rather not","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"Nana Bizz pays the Bizzington bank the {c5} instead of buying a cricket bat. What did Nana Bizz give up?","opts":["Having it this week","The loan itself","Nothing — repayments do not count","{c5} for nothing"],"after":"Keeping a repayment has a cost too, and naming it is honest. What you get back is a kept promise and a cheaper next loan."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-4-59","bands":["sprout","builder"],"grp":"card:c6d"},"f-assess-owe-5-0":{"kind":"question","src":"assess:OWE-5#0","level":6,"topics":["card:c6d","ch:c6","goal:OWE-5","who:pip"],"key":"OWE-5#0#0","title":"Trust is a memory","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"Somebody repaid everything on time for a year. What changed?","opts":["They can borrow more, and usually for less","The rate went up","Nothing","They owe more"],"after":"A record of paying is worth money. It is the only thing a lender has to go on, so it is priced."},"source":"Chapter 6 · Borrowing · a question to come back to","id":"f-assess-owe-5-0","bands":["sprout","builder"],"grp":"card:c6d"},"f-assess-owe-5-0why":{"kind":"why","src":"assess:OWE-5#0why","level":6,"topics":["card:c6d","ch:c6","goal:OWE-5","who:pip"],"card":"c6d","title":"Trust is a memory","body":"A record of paying is worth money. It is the only thing a lender has to go on, so it is priced.","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","source":"Chapter 6 · Borrowing · why, said again","id":"f-assess-owe-5-0why","bands":["sprout","builder"],"grp":"card:c6d"},"f-assess-owe-5-1":{"kind":"question","src":"assess:OWE-5#1","level":6,"topics":["card:c6d","ch:c6","goal:OWE-5","who:pip"],"key":"OWE-5#1#0","title":"Trust is a memory","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"What does a lender actually not know about you?","opts":["Whether you will pay next time","Your name","What you borrowed before","What you paid"],"after":"They can only see backwards. That is why the past is priced so heavily — it is the only evidence there is."},"source":"Chapter 6 · Borrowing · a question to come back to","id":"f-assess-owe-5-1","bands":["sprout","builder"],"grp":"card:c6d"},"f-assess-owe-5-1why":{"kind":"why","src":"assess:OWE-5#1why","level":6,"topics":["card:c6d","ch:c6","goal:OWE-5","who:pip"],"card":"c6d","title":"Trust is a memory","body":"They can only see backwards. That is why the past is priced so heavily — it is the only evidence there is.","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","source":"Chapter 6 · Borrowing · why, said again","id":"f-assess-owe-5-1why","bands":["sprout","builder"],"grp":"card:c6d"},"f-assess-owe-5-2":{"kind":"question","src":"assess:OWE-5#2","level":6,"topics":["card:c6d","ch:c6","goal:OWE-5","who:pip"],"key":"OWE-5#2#0","title":"Trust is a memory","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"A record is damaged. Can it be repaired?","opts":["Yes, by a run of kept payments — slowly","Only by moving bank","Never","Instantly, by paying it off"],"after":"It goes up slowly and down quickly, which is unfair-feeling and true. Knowing that in advance changes how much a missed one matters."},"source":"Chapter 6 · Borrowing · a question to come back to","id":"f-assess-owe-5-2","bands":["sprout","builder"],"grp":"card:c6d"},"f-assess-owe-5-2why":{"kind":"why","src":"assess:OWE-5#2why","level":6,"topics":["card:c6d","ch:c6","goal:OWE-5","who:pip"],"card":"c6d","title":"Trust is a memory","body":"It goes up slowly and down quickly, which is unfair-feeling and true. Knowing that in advance changes how much a missed one matters.","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","source":"Chapter 6 · Borrowing · why, said again","id":"f-assess-owe-5-2why","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-5-1":{"kind":"question","src":"gen:OWE-5~1","level":6,"topics":["card:c6d","ch:c6","goal:OWE-5","who:pip"],"key":"OWE-5~1#0","title":"Trust is a memory","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"Why does a lender care what Nana Bizz did last time?","opts":["It is the best clue to what Nana Bizz will do next time","To tell others","Out of curiosity","It does not care"],"after":"A lender cannot see the future. The past is all they have, which is why it matters."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-5-1","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-5-1-why":{"kind":"why","src":"gen:OWE-5~1#why","level":6,"topics":["card:c6d","ch:c6","goal:OWE-5","who:pip"],"card":"c6d","title":"Trust is a memory","body":"A lender cannot see the future. The past is all they have, which is why it matters.","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","source":"Chapter 6 · Borrowing · why, said again","id":"f-gen-owe-5-1-why","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-5-2":{"kind":"question","src":"gen:OWE-5~2","level":6,"topics":["card:c6d","ch:c6","goal:OWE-5","who:pip"],"key":"OWE-5~2#0","title":"Trust is a memory","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"Bea repaid Mags on time every week for 6 months. What changed for next time?","opts":["Bea can usually borrow more, and for less","Bea owes more","The price of borrowing goes up","Nothing"],"after":"A lender is guessing about the future. A run of kept payments is the best evidence there is, and it makes the guess cheaper."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-5-2","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-5-2-why":{"kind":"why","src":"gen:OWE-5~2#why","level":6,"topics":["card:c6d","ch:c6","goal:OWE-5","who:pip"],"card":"c6d","title":"Trust is a memory","body":"A lender is guessing about the future. A run of kept payments is the best evidence there is, and it makes the guess cheaper.","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","source":"Chapter 6 · Borrowing · why, said again","id":"f-gen-owe-5-2-why","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-5-3":{"kind":"question","src":"gen:OWE-5~3","level":6,"topics":["card:c6d","ch:c6","goal:OWE-5","who:pip"],"key":"OWE-5~3#0","title":"Trust is a memory","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"Nana Bizz repaid the lending desk at the bank on time every week for 7 months. What changed for next time?","opts":["Nana Bizz can usually borrow more, and for less","The price of borrowing goes up","Nothing","Nana Bizz owes more"],"after":"A lender is guessing about the future. A run of kept payments is the best evidence there is, and it makes the guess cheaper."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-5-3","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-5-6":{"kind":"question","src":"gen:OWE-5~6","level":6,"topics":["card:c6d","ch:c6","goal:OWE-5","who:pip"],"key":"OWE-5~6#0","title":"Trust is a memory","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"What does the lending desk at the bank not know about Bo, however well they know each other?","opts":["Whether Bo will pay next time","What Bo paid back before","What Bo borrowed before","Bo’s name"],"after":"Everything a lender knows is about the past. What you did last time is the only clue to next time — which is why it matters so much."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-5-6","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-5-6-why":{"kind":"why","src":"gen:OWE-5~6#why","level":6,"topics":["card:c6d","ch:c6","goal:OWE-5","who:pip"],"card":"c6d","title":"Trust is a memory","body":"Everything a lender knows is about the past. What you did last time is the only clue to next time — which is why it matters so much.","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","source":"Chapter 6 · Borrowing · why, said again","id":"f-gen-owe-5-6-why","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-5-7":{"kind":"question","src":"gen:OWE-5~7","level":6,"topics":["card:c6d","ch:c6","goal:OWE-5","who:pip"],"key":"OWE-5~7#0","title":"Trust is a memory","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"Mags missed 2 payments to Nana Bizz last spring. Can that record be repaired?","opts":["Yes, by a run of kept payments — slowly","Only by moving to another bank","Yes, at once, by paying it all off","Never"],"after":"Trust is a memory, and memories are rebuilt one kept promise at a time. It works in both directions."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-5-7","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-5-7-why":{"kind":"why","src":"gen:OWE-5~7#why","level":6,"topics":["card:c6d","ch:c6","goal:OWE-5","who:pip"],"card":"c6d","title":"Trust is a memory","body":"Trust is a memory, and memories are rebuilt one kept promise at a time. It works in both directions.","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","source":"Chapter 6 · Borrowing · why, said again","id":"f-gen-owe-5-7-why","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-5-8":{"kind":"question","src":"gen:OWE-5~8","level":6,"topics":["card:c6d","ch:c6","goal:OWE-5","who:pip"],"key":"OWE-5~8#0","title":"Trust is a memory","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"The bank offers Pip a cheaper loan than last year. What might be the reason?","opts":["Pip paid every week on time last year","Interest is free now","Luck","The bank likes Pip’s name"],"after":"A good record lowers the risk for the lender — and a lower risk can mean a lower price."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-5-8","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-5-8-why":{"kind":"why","src":"gen:OWE-5~8#why","level":6,"topics":["card:c6d","ch:c6","goal:OWE-5","who:pip"],"card":"c6d","title":"Trust is a memory","body":"A good record lowers the risk for the lender — and a lower risk can mean a lower price.","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","source":"Chapter 6 · Borrowing · why, said again","id":"f-gen-owe-5-8-why","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-5-9":{"kind":"question","src":"gen:OWE-5~9","level":6,"topics":["card:c6d","ch:c6","goal:OWE-5","who:pip"],"key":"OWE-5~9#0","title":"Trust is a memory","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"Bea borrowed small amounts from Nana Bizz and always paid back on time. Now Bea asks for more. What is Nana likely to think?","opts":["Bea has shown they keep their word","That Bea should never borrow again","That Bea borrows too much","Nothing has changed"],"after":"A record of kept promises is the best reason a lender has to trust you again."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-5-9","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-5-9-why":{"kind":"why","src":"gen:OWE-5~9#why","level":6,"topics":["card:c6d","ch:c6","goal:OWE-5","who:pip"],"card":"c6d","title":"Trust is a memory","body":"A record of kept promises is the best reason a lender has to trust you again.","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","source":"Chapter 6 · Borrowing · why, said again","id":"f-gen-owe-5-9-why","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-5-10":{"kind":"question","src":"gen:OWE-5~10","level":6,"topics":["card:c6d","ch:c6","goal:OWE-5","who:pip"],"key":"OWE-5~10#0","title":"Trust is a memory","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"Bo missed several payments to the Bizzington bank. What happens the next time Bo asks to borrow?","opts":["Bo may be offered less, or at a higher price","Borrowing is closed for ever","Bo is offered more, to help catch up","Exactly the same as before"],"after":"Missed payments make lending riskier, so it costs more or comes smaller. Not for ever — kept payments bring it back."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-5-10","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-5-10-why":{"kind":"why","src":"gen:OWE-5~10#why","level":6,"topics":["card:c6d","ch:c6","goal:OWE-5","who:pip"],"card":"c6d","title":"Trust is a memory","body":"Missed payments make lending riskier, so it costs more or comes smaller. Not for ever — kept payments bring it back.","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","source":"Chapter 6 · Borrowing · why, said again","id":"f-gen-owe-5-10-why","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-5-15":{"kind":"question","src":"gen:OWE-5~15","level":6,"topics":["card:c6d","ch:c6","goal:OWE-5","who:pip"],"key":"OWE-5~15#0","title":"Trust is a memory","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"Pip lent Bea a cricket bat and got it back broken, with no word. Next time Bea asks, what might Pip say?","opts":["“Not this time” — or “only if you look after it”","“Take two!”","“Of course!” as before","Nothing changes"],"after":"Lending money or things works the same way. How it came back last time decides the next answer."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-5-15","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-5-15-why":{"kind":"why","src":"gen:OWE-5~15#why","level":6,"topics":["card:c6d","ch:c6","goal:OWE-5","who:pip"],"card":"c6d","title":"Trust is a memory","body":"Lending money or things works the same way. How it came back last time decides the next answer.","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","source":"Chapter 6 · Borrowing · why, said again","id":"f-gen-owe-5-15-why","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-5-23":{"kind":"question","src":"gen:OWE-5~23","level":6,"topics":["card:c6d","ch:c6","goal:OWE-5","who:pip"],"key":"OWE-5~23#0","title":"Trust is a memory","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"Bo missed two payments last year and paid every one since. What is happening to Bo’s record?","opts":["It is slowly getting better with each kept payment","It is ruined for ever","Nothing","It is wiped clean at once"],"after":"Trust grows back the way it was lost: one payment at a time."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-5-23","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-5-23-why":{"kind":"why","src":"gen:OWE-5~23#why","level":6,"topics":["card:c6d","ch:c6","goal:OWE-5","who:pip"],"card":"c6d","title":"Trust is a memory","body":"Trust grows back the way it was lost: one payment at a time.","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","source":"Chapter 6 · Borrowing · why, said again","id":"f-gen-owe-5-23-why","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-5-53":{"kind":"question","src":"gen:OWE-5~53","level":6,"topics":["card:c6d","ch:c6","goal:OWE-5","who:pip"],"key":"OWE-5~53#0","title":"Trust is a memory","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"Mags missed 4 payments to the Bizzington bank last spring. Can that record be repaired?","opts":["Yes, by a run of kept payments — slowly","Yes, at once, by paying it all off","Never","Only by moving to another bank"],"after":"Trust is a memory, and memories are rebuilt one kept promise at a time. It works in both directions."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-5-53","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-5-60":{"kind":"question","src":"gen:OWE-5~60","level":6,"topics":["card:c6d","ch:c6","goal:OWE-5","who:pip"],"key":"OWE-5~60#0","title":"Trust is a memory","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"Bea missed several payments to Nana Bizz. What happens the next time Bea asks to borrow?","opts":["Bea may be offered less, or at a higher price","Borrowing is closed for ever","Exactly the same as before","Bea is offered more, to help catch up"],"after":"Missed payments make lending riskier, so it costs more or comes smaller. Not for ever — kept payments bring it back."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-5-60","bands":["sprout","builder"],"grp":"card:c6d"},"f-assess-owe-6-0":{"kind":"question","src":"assess:OWE-6#0","level":6,"topics":["card:x-ch8","ch:c6","goal:OWE-6","who:nana"],"key":"OWE-6#0#0","title":"Waiting against borrowing","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","play":{"q":"800 now with 80 of interest, or 800 in three weeks. What are you actually choosing?","opts":["Whether three weeks of having it is worth 80 to you","Between good and bad","The cheaper option","Whether to save"],"after":"Both are legitimate. Once it is put like that, it is a preference with a price on it rather than a test you can fail."},"source":"Chapter 6 · Borrowing · a question to come back to","id":"f-assess-owe-6-0","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-assess-owe-6-0why":{"kind":"why","src":"assess:OWE-6#0why","level":6,"topics":["card:x-ch8","ch:c6","goal:OWE-6","who:nana"],"card":"x-ch8","title":"Waiting against borrowing","body":"Both are legitimate. Once it is put like that, it is a preference with a price on it rather than a test you can fail.","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · why, said again","id":"f-assess-owe-6-0why","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-assess-owe-6-1":{"kind":"question","src":"assess:OWE-6#1","level":6,"topics":["card:x-ch8","ch:c6","goal:OWE-6","who:nana"],"key":"OWE-6#1#0","title":"Waiting against borrowing","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","play":{"q":"When does borrowing win that comparison outright?","opts":["When having it sooner earns or saves more than the interest","When the interest is small","When you want it a lot","Never"],"after":"If the cart earns 200 in the three weeks it costs 80 to have early, waiting is the expensive option."},"source":"Chapter 6 · Borrowing · a question to come back to","id":"f-assess-owe-6-1","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-assess-owe-6-1why":{"kind":"why","src":"assess:OWE-6#1why","level":6,"topics":["card:x-ch8","ch:c6","goal:OWE-6","who:nana"],"card":"x-ch8","title":"Waiting against borrowing","body":"If the cart earns 200 in the three weeks it costs 80 to have early, waiting is the expensive option.","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · why, said again","id":"f-assess-owe-6-1why","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-assess-owe-6-2":{"kind":"question","src":"assess:OWE-6#2","level":6,"topics":["card:x-ch8","ch:c6","goal:OWE-6","who:nana"],"key":"OWE-6#2#0","title":"Waiting against borrowing","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","play":{"q":"What makes this comparison possible at all?","opts":["Knowing both totals","The advert","Guessing","Asking somebody"],"after":"You cannot weigh two things until they are in the same units. Working out both totals is the entire move."},"source":"Chapter 6 · Borrowing · a question to come back to","id":"f-assess-owe-6-2","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-assess-owe-6-2why":{"kind":"why","src":"assess:OWE-6#2why","level":6,"topics":["card:x-ch8","ch:c6","goal:OWE-6","who:nana"],"card":"x-ch8","title":"Waiting against borrowing","body":"You cannot weigh two things until they are in the same units. Working out both totals is the entire move.","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · why, said again","id":"f-assess-owe-6-2why","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-gen-owe-3-149":{"kind":"question","src":"gen:OWE-3~149","level":6,"topics":["card:c6c","ch:c6","goal:OWE-3","who:nana"],"key":"OWE-3~149#0","title":"Good reasons and bad ones","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","play":{"q":"Pip borrows for a fair ticket and pays it back over 9 weeks. What is the catch?","opts":["Pip is still paying after the fun is over","There is no catch","Borrowing is against the rules","Pip pays back less than was borrowed"],"after":"The fun lasts a day; the payments last 9 weeks. That is worth knowing before, not after — it is a price, not a punishment."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-3-149","bands":["sprout","builder"],"grp":"card:c6c"},"f-gen-owe-3-602":{"kind":"question","src":"gen:OWE-3~602","level":6,"topics":["card:c6c","ch:c6","goal:OWE-3","who:nana"],"key":"OWE-3~602#0","title":"Good reasons and bad ones","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","play":{"q":"Nana Bizz could borrow {c30} for a cart, paying back {c32}. While the loan runs, a cart would earn {c3}. Is that a good reason to borrow?","opts":["Yes — it earns {c3}, more than the {c2} it costs","Yes — borrowing for work always pays","Only if the cart is brand new","No — borrowing is always a bad idea"],"after":"The loan costs {c32} − {c30} = {c2}. Set that against the {c3} it earns. Borrowing is a tool with a price — the numbers decide, not a rule."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-3-602","bands":["sprout","builder"],"grp":"card:c6c"},"f-gen-owe-4-123":{"kind":"question","src":"gen:OWE-4~123","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"key":"OWE-4~123#0","title":"Paying it when you would rather not","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"Mags pays the lending desk at the bank the {c2} instead of buying a lantern. What did Mags give up?","opts":["Having it this week","Nothing — repayments do not count","{c2} for nothing","The loan itself"],"after":"Keeping a repayment has a cost too, and naming it is honest. What you get back is a kept promise and a cheaper next loan."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-4-123","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-4-162":{"kind":"question","src":"gen:OWE-4~162","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"key":"OWE-4~162#0","title":"Paying it when you would rather not","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"A repayment of {c3} to Mags is due, and Bo wants a board game for {c7}. What is the honest way to see it?","opts":["Its real cost is {c7} plus a broken promise","Skip it once; nobody minds","The repayment is unfair","The money is not really Bo’s"],"after":"A repayment is a promise already made. Spending its money means paying for the thing and for breaking the promise."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-4-162","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-4-170":{"kind":"question","src":"gen:OWE-4~170","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"key":"OWE-4~170#0","title":"Paying it when you would rather not","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"Mags pays Nana Bizz the {c2} instead of buying a bicycle bell. What did Mags give up?","opts":["Having it this week","The loan itself","Nothing — repayments do not count","{c2} for nothing"],"after":"Keeping a repayment has a cost too, and naming it is honest. What you get back is a kept promise and a cheaper next loan."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-4-170","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-4-309":{"kind":"question","src":"gen:OWE-4~309","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"key":"OWE-4~309#0","title":"Paying it when you would rather not","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"Bo pays the Bizzington bank the {c6} instead of buying a bicycle bell. What did Bo give up?","opts":["Having it this week","{c6} for nothing","The loan itself","Nothing — repayments do not count"],"after":"Keeping a repayment has a cost too, and naming it is honest. What you get back is a kept promise and a cheaper next loan."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-4-309","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-4-471":{"kind":"question","src":"gen:OWE-4~471","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"key":"OWE-4~471#0","title":"Paying it when you would rather not","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"Bo pays Nana Bizz the {c3} instead of buying a board game. What did Bo give up?","opts":["Having it this week","The loan itself","Nothing — repayments do not count","{c3} for nothing"],"after":"Keeping a repayment has a cost too, and naming it is honest. What you get back is a kept promise and a cheaper next loan."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-4-471","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-4-558":{"kind":"question","src":"gen:OWE-4~558","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"key":"OWE-4~558#0","title":"Paying it when you would rather not","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"A repayment of {c5} to Mags is due, and Nana Bizz wants a cricket bat for {c8}. What is the honest way to see it?","opts":["Its real cost is {c8} plus a broken promise","The money is not really Nana Bizz’s","Skip it once; nobody minds","The repayment is unfair"],"after":"A repayment is a promise already made. Spending its money means paying for the thing and for breaking the promise."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-4-558","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-4-734":{"kind":"question","src":"gen:OWE-4~734","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"key":"OWE-4~734#0","title":"Paying it when you would rather not","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"Pip pays the Bizzington bank the {c2} instead of buying a board game. What did Pip give up?","opts":["Having it this week","Nothing — repayments do not count","The loan itself","{c2} for nothing"],"after":"Keeping a repayment has a cost too, and naming it is honest. What you get back is a kept promise and a cheaper next loan."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-4-734","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-4-761":{"kind":"question","src":"gen:OWE-4~761","level":6,"topics":["card:c6d","ch:c6","goal:OWE-4","who:pip"],"key":"OWE-4~761#0","title":"Paying it when you would rather not","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"A repayment of {c3} to the lending desk at the bank is due, and Pip wants a cricket bat for {c9}. What is the honest way to see it?","opts":["Its real cost is {c9} plus a broken promise","The money is not really Pip’s","The repayment is unfair","Skip it once; nobody minds"],"after":"A repayment is a promise already made. Spending its money means paying for the thing and for breaking the promise."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-4-761","bands":["sprout","builder"],"grp":"card:c6d"},"f-gen-owe-5-161":{"kind":"question","src":"gen:OWE-5~161","level":6,"topics":["card:c6d","ch:c6","goal:OWE-5","who:pip"],"key":"OWE-5~161#0","title":"Trust is a memory","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","play":{"q":"What does Nana Bizz not know about Pip, however well they know each other?","opts":["Whether Pip will pay next time","Pip’s name","What Pip paid back before","What Pip borrowed before"],"after":"Everything a lender knows is about the past. What you did last time is the only clue to next time — which is why it matters so much."},"source":"Chapter 6 · Borrowing · the same idea in a new story","id":"f-gen-owe-5-161","bands":["sprout","builder"],"grp":"card:c6d"},"f-sprout-c6a-eg":{"kind":"example","src":"sprout:c6a#eg","level":6,"topics":["card:c6a","ch:c6","who:nana"],"bands":["sprout"],"title":"Interest, both ways","body":"Borrowing is nothing to feel bad about. It is a tool with a price. Find the price first.","route":"#/atlas/c6a","cta":"Open the lesson","maths":"M10","source":"Chapter 6 · Borrowing · read for a Sprout","id":"f-sprout-c6a-eg","grp":"card:c6a"},"f-sprout-c6b-teach":{"kind":"lesson","src":"sprout:c6b#teach","level":6,"topics":["card:c6b","ch:c6","who:pip"],"bands":["sprout"],"title":"The number that matters","body":"Sellers show you the small monthly payment. That is not the real cost. Add up everything you pay back. Then take away what you borrowed. That is the real cost.","route":"#/atlas/c6b","cta":"Open the lesson","maths":"M9","card":"c6b","source":"Chapter 6 · Borrowing · read for a Sprout","id":"f-sprout-c6b-teach","grp":"card:c6b"},"f-sprout-c6b-eg":{"kind":"example","src":"sprout:c6b#eg","level":6,"topics":["card:c6b","ch:c6","who:pip"],"bands":["sprout"],"title":"The number that matters","body":"Borrow 1,000. Pay back 110 a month for a year. That is 1,320 in all. The loan cost 320.","route":"#/atlas/c6b","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · read for a Sprout","id":"f-sprout-c6b-eg","grp":"card:c6b"},"f-sprout-c6c-eg":{"kind":"example","src":"sprout:c6c#eg","level":6,"topics":["card:c6c","ch:c6","who:nana"],"bands":["sprout"],"title":"Good reasons and bad ones","body":"Nana borrowed to buy umbrellas to sell. That loan made money. Her festival loan did not. She would still do it again.","route":"#/atlas/c6c","cta":"Open the lesson","maths":"M4","source":"Chapter 6 · Borrowing · read for a Sprout","id":"f-sprout-c6c-eg","grp":"card:c6c"},"f-sprout-c6d-eg":{"kind":"example","src":"sprout:c6d#eg","level":6,"topics":["card:c6d","ch:c6","who:pip"],"bands":["sprout"],"title":"Trust is a memory","body":"Here it is the trust score. Pay back, and it goes up.","route":"#/atlas/c6d","cta":"Open the lesson","maths":"M5","source":"Chapter 6 · Borrowing · read for a Sprout","id":"f-sprout-c6d-eg","grp":"card:c6d"},"f-sprout-x-ch8-teach":{"kind":"lesson","src":"sprout:x-ch8#teach","level":6,"topics":["card:x-ch8","ch:c6","who:nana"],"bands":["sprout"],"title":"What waiting costs, and what it saves","body":"Buying now and saving up are both fine answers. To choose well, write down both sides. What extra do you pay if you buy now? What do you miss out on if you wait? Then pick. You will know why you chose.","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","card":"x-ch8","source":"Chapter 6 · Borrowing · read for a Sprout","id":"f-sprout-x-ch8-teach","grp":"card:x-ch8"},"f-item-c6b-how":{"kind":"showhow","src":"item:c6b#how","level":6,"topics":["card:c6b","ch:c6","who:pip"],"title":"What the loan really cost","body":"Say you borrow 300 and repay 40 a month for 9 months.\nEverything handed back: 40 × 9 = 360.\nTake away the 300 borrowed: 360 − 300. That gap is what the loan cost.","route":"#/atlas/c6b","cta":"Have a go","maths":"M9","source":"Chapter 6 · Borrowing · The number that matters · with Pip","id":"f-item-c6b-how","bands":["sprout","builder"],"grp":"card:c6b"},"f-item-c6e-how":{"kind":"showhow","src":"item:c6e#how","level":6,"topics":["card:c6e","ch:c6","who:nana"],"title":"What is left after the payment","body":"Say 30 comes in, costs are 18, and a payment would be 5.\nAfter costs: 30 − 18 = 12.\nAfter the payment: 12 − 5 = 7 left to choose about. Now try Bea’s week.","route":"#/atlas/c6e","cta":"Have a go","maths":"M10","source":"Chapter 6 · Borrowing · Can the payment fit? · with Nana Bizz","id":"f-item-c6e-how","bands":["sprout","builder"],"grp":"card:c6e"},"f-genhow-choose-8-1":{"kind":"showhow","src":"genhow:CHOOSE-8~1","level":6,"topics":["card:x-ch8","ch:c6","who:nana","goal:CHOOSE-8"],"title":"Weighing waiting against buying now","body":"A board game costs {c50}. Bea saves {c12} every week. How many weeks until there is enough?\n4 weeks gives {c48}, still {c2} short — so it takes 5 weeks, with {c10} spare. Now the waiting has a number, and you can weigh it against buying now.","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · Show me how","id":"f-genhow-choose-8-1","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-genhow-choose-8-4":{"kind":"showhow","src":"genhow:CHOOSE-8~4","level":6,"topics":["card:x-ch8","ch:c6","who:nana","goal:CHOOSE-8"],"title":"Weighing waiting against buying now","body":"A lantern for the stall costs {c23}. Nana Bizz has {c1} and saves {c8} a week. How many weeks until there is enough?\n{c23} − {c1} = {c22} still to find. 2 weeks gives {c16}, not quite enough, so it takes 3 weeks. That is the waiting column, with a number in it.","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · Show me how","id":"f-genhow-choose-8-4","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-genhow-choose-8-10":{"kind":"showhow","src":"genhow:CHOOSE-8~10","level":6,"topics":["card:x-ch8","ch:c6","who:nana","goal:CHOOSE-8"],"title":"Weighing waiting against buying now","body":"A lantern costs {c9}. Nana Bizz saves {c6} every week. How many weeks until there is enough?\n1 weeks gives {c6}, still {c3} short — so it takes 2 weeks, with {c3} spare. Now the waiting has a number, and you can weigh it against buying now.","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · Show me how","id":"f-genhow-choose-8-10","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-genhow-choose-8-174":{"kind":"showhow","src":"genhow:CHOOSE-8~174","level":6,"topics":["card:x-ch8","ch:c6","who:nana","goal:CHOOSE-8"],"title":"Weighing waiting against buying now","body":"A paint set costs {c31}. Bo saves {c8} every week. How many weeks until there is enough?\n3 weeks gives {c24}, still {c7} short — so it takes 4 weeks, with {c1} spare. Now the waiting has a number, and you can weigh it against buying now.","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · Show me how","id":"f-genhow-choose-8-174","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-genhow-grow-2-1":{"kind":"showhow","src":"genhow:GROW-2~1","level":6,"topics":["card:c6a","ch:c6","who:nana","goal:GROW-2"],"title":"Interest, in coins","body":"In a story, the bank on Clocktower Square pays 4 in every 100 a year. Bea keeps {c300} there all year. How much interest is that?\n{c300} holds 3 lots of {c100}; each earns {c4}, so {c12} in all. Rent the bank pays for using Bea’s money.","route":"#/atlas/c6a","cta":"Open the lesson","maths":"M10","source":"Chapter 6 · Borrowing · Show me how","id":"f-genhow-grow-2-1","bands":["sprout","builder"],"grp":"card:c6a"},"f-genhow-grow-2-2":{"kind":"showhow","src":"genhow:GROW-2~2","level":6,"topics":["card:c6a","ch:c6","who:nana","goal:GROW-2"],"title":"Interest, in coins","body":"A bank in a story pays 10 in every 100 a year. Nana Bizz leaves {c300} in it for a year. How much interest is that?\n{c300} is 3 lots of {c100}, and each lot earns {c10}. Interest is rent the bank pays for your money.","route":"#/atlas/c6a","cta":"Open the lesson","maths":"M10","source":"Chapter 6 · Borrowing · Show me how","id":"f-genhow-grow-2-2","bands":["sprout","builder"],"grp":"card:c6a"},"f-genhow-owe-1-9":{"kind":"showhow","src":"genhow:OWE-1~9","level":6,"topics":["card:c6a","ch:c6","who:nana","goal:OWE-1"],"title":"Borrowing has a price","body":"Pip borrows a handcart from Mags, who charges {c2} for every week it is kept. Pip keeps it 2 weeks. What did borrowing it cost?\n{c2} × 2 = {c4}. Borrowing has a price, and the longer you keep it, the more you pay.","route":"#/atlas/c6a","cta":"Open the lesson","maths":"M10","source":"Chapter 6 · Borrowing · Show me how","id":"f-genhow-owe-1-9","bands":["sprout","builder"],"grp":"card:c6a"},"f-genhow-owe-2-1":{"kind":"showhow","src":"genhow:OWE-2~1","level":6,"topics":["card:c6b","ch:c6","who:pip","goal:OWE-2"],"title":"The number that matters","body":"You borrow {c51} and pay it back as 5 weekly payments of {c12}. How much more than you borrowed did you pay?\nEverything paid back is 5 × {c12} = {c60}; take away the {c51} borrowed. That difference is the number that matters.","route":"#/atlas/c6b","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · Show me how","id":"f-genhow-owe-2-1","bands":["sprout","builder"],"grp":"card:c6b"},"f-genhow-owe-2-2":{"kind":"showhow","src":"genhow:OWE-2~2","level":6,"topics":["card:c6b","ch:c6","who:pip","goal:OWE-2"],"title":"The number that matters","body":"Bo borrows to buy a bicycle and repays {c6} a week for 3 weeks, plus a {c8} fee at the end. What does he hand over in total?\n3 × {c6} = {c18}, plus {c8}: {c26}. That total, not the weekly {c6}, is the number to read first.","route":"#/atlas/c6b","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · Show me how","id":"f-genhow-owe-2-2","bands":["sprout","builder"],"grp":"card:c6b"},"f-genhow-owe-6-1":{"kind":"showhow","src":"genhow:OWE-6~1","level":6,"topics":["card:x-ch8","ch:c6","who:nana","goal:OWE-6"],"title":"Waiting against borrowing","body":"A lantern costs {c44}. Bea has {c12} and saves {c8} a week. How many weeks of waiting is that?\n{c44} − {c12} = {c32} still to find, at {c8} a week: 4 weeks. That is the cost of waiting — in weeks.","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · Show me how","id":"f-genhow-owe-6-1","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-genhow-owe-6-2":{"kind":"showhow","src":"genhow:OWE-6~2","level":6,"topics":["card:x-ch8","ch:c6","who:nana","goal:OWE-6"],"title":"Waiting against borrowing","body":"Borrowing would get Bea a bicycle bell 5 weeks sooner, for {c45} extra. How much is each week of having it sooner costing?\n{c45} ÷ 5 weeks = {c9} a week. Now both sides are in the same units — is one week of having it worth {c9} to Bea?","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · Show me how","id":"f-genhow-owe-6-2","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-genhow-owe-6-3":{"kind":"showhow","src":"genhow:OWE-6~3","level":6,"topics":["card:x-ch8","ch:c6","who:nana","goal:OWE-6"],"title":"Waiting against borrowing","body":"A bicycle bell costs {c70}. Bea has {c15} and saves {c11} a week. How many weeks of waiting is that?\n{c70} − {c15} = {c55} still to find, at {c11} a week: 5 weeks. That is the cost of waiting — in weeks.","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · Show me how","id":"f-genhow-owe-6-3","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-genhow-owe-6-4":{"kind":"showhow","src":"genhow:OWE-6~4","level":6,"topics":["card:x-ch8","ch:c6","who:nana","goal:OWE-6"],"title":"Waiting against borrowing","body":"A cricket bat costs {c38}. Bo has {c14} and saves {c12} a week. How many weeks of waiting is that?\n{c38} − {c14} = {c24} still to find, at {c12} a week: 2 weeks. That is the cost of waiting — in weeks.","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · Show me how","id":"f-genhow-owe-6-4","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-genhow-owe-6-6":{"kind":"showhow","src":"genhow:OWE-6~6","level":6,"topics":["card:x-ch8","ch:c6","who:nana","goal:OWE-6"],"title":"Waiting against borrowing","body":"A board game costs {c27}. Nana Bizz has {c6} and saves {c7} a week. How many weeks of waiting is that?\n{c27} − {c6} = {c21} still to find, at {c7} a week: 3 weeks. That is the cost of waiting — in weeks.","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · Show me how","id":"f-genhow-owe-6-6","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-genhow-owe-6-15":{"kind":"showhow","src":"genhow:OWE-6~15","level":6,"topics":["card:x-ch8","ch:c6","who:nana","goal:OWE-6"],"title":"Waiting against borrowing","body":"Borrowing gets Nana Bizz a bicycle 4 weeks earlier, and costs {c12} more than saving up. What does each week of riding sooner cost?\n{c12} ÷ 4 = {c3} a week. Now waiting and borrowing are in the same units, and Nana Bizz can ask: is a week of riding worth {c3}?","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · Show me how","id":"f-genhow-owe-6-15","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-genhow-owe-6-18":{"kind":"showhow","src":"genhow:OWE-6~18","level":6,"topics":["card:x-ch8","ch:c6","who:nana","goal:OWE-6"],"title":"Waiting against borrowing","body":"A cricket bat costs {c55}. Nana Bizz has {c15} and saves {c10} a week. How many weeks of waiting is that?\n{c55} − {c15} = {c40} still to find, at {c10} a week: 4 weeks. That is the cost of waiting — in weeks.","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · Show me how","id":"f-genhow-owe-6-18","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-genhow-owe-6-42":{"kind":"showhow","src":"genhow:OWE-6~42","level":6,"topics":["card:x-ch8","ch:c6","who:nana","goal:OWE-6"],"title":"Waiting against borrowing","body":"A paint set costs {c43}. Pip has {c13} and saves {c6} a week. How many weeks of waiting is that?\n{c43} − {c13} = {c30} still to find, at {c6} a week: 5 weeks. That is the cost of waiting — in weeks.","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · Show me how","id":"f-genhow-owe-6-42","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-genhow-owe-6-58":{"kind":"showhow","src":"genhow:OWE-6~58","level":6,"topics":["card:x-ch8","ch:c6","who:nana","goal:OWE-6"],"title":"Waiting against borrowing","body":"A kite costs {c39}. Mags has {c15} and saves {c8} a week. How many weeks of waiting is that?\n{c39} − {c15} = {c24} still to find, at {c8} a week: 3 weeks. That is the cost of waiting — in weeks.","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · Show me how","id":"f-genhow-owe-6-58","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-genhow-owe-6-93":{"kind":"showhow","src":"genhow:OWE-6~93","level":6,"topics":["card:x-ch8","ch:c6","who:nana","goal:OWE-6"],"title":"Waiting against borrowing","body":"A paint set costs {c33}. Nana Bizz has {c11} and saves {c11} a week. How many weeks of waiting is that?\n{c33} − {c11} = {c22} still to find, at {c11} a week: 2 weeks. That is the cost of waiting — in weeks.","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · Show me how","id":"f-genhow-owe-6-93","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-genhow-owe-6-119":{"kind":"showhow","src":"genhow:OWE-6~119","level":6,"topics":["card:x-ch8","ch:c6","who:nana","goal:OWE-6"],"title":"Waiting against borrowing","body":"A bicycle bell costs {c37}. Nana Bizz has {c9} and saves {c7} a week. How many weeks of waiting is that?\n{c37} − {c9} = {c28} still to find, at {c7} a week: 4 weeks. That is the cost of waiting — in weeks.","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · Show me how","id":"f-genhow-owe-6-119","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-genhow-owe-6-136":{"kind":"showhow","src":"genhow:OWE-6~136","level":6,"topics":["card:x-ch8","ch:c6","who:nana","goal:OWE-6"],"title":"Waiting against borrowing","body":"A bicycle bell costs {c42}. Pip has {c12} and saves {c10} a week. How many weeks of waiting is that?\n{c42} − {c12} = {c30} still to find, at {c10} a week: 3 weeks. That is the cost of waiting — in weeks.","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · Show me how","id":"f-genhow-owe-6-136","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-genhow-owe-6-142":{"kind":"showhow","src":"genhow:OWE-6~142","level":6,"topics":["card:x-ch8","ch:c6","who:nana","goal:OWE-6"],"title":"Waiting against borrowing","body":"A board game costs {c34}. Mags has {c14} and saves {c10} a week. How many weeks of waiting is that?\n{c34} − {c14} = {c20} still to find, at {c10} a week: 2 weeks. That is the cost of waiting — in weeks.","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · Show me how","id":"f-genhow-owe-6-142","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-genhow-owe-6-192":{"kind":"showhow","src":"genhow:OWE-6~192","level":6,"topics":["card:x-ch8","ch:c6","who:nana","goal:OWE-6"],"title":"Waiting against borrowing","body":"A lantern costs {c57}. Bo has {c7} and saves {c10} a week. How many weeks of waiting is that?\n{c57} − {c7} = {c50} still to find, at {c10} a week: 5 weeks. That is the cost of waiting — in weeks.","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · Show me how","id":"f-genhow-owe-6-192","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-genhow-owe-6-423":{"kind":"showhow","src":"genhow:OWE-6~423","level":6,"topics":["card:x-ch8","ch:c6","who:nana","goal:OWE-6"],"title":"Waiting against borrowing","body":"A bicycle bell costs {c29}. Bo has {c13} and saves {c8} a week. How many weeks of waiting is that?\n{c29} − {c13} = {c16} still to find, at {c8} a week: 2 weeks. That is the cost of waiting — in weeks.","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · Show me how","id":"f-genhow-owe-6-423","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-genhow-owe-6-1200":{"kind":"showhow","src":"genhow:OWE-6~1200","level":6,"topics":["card:x-ch8","ch:c6","who:nana","goal:OWE-6"],"title":"Waiting against borrowing","body":"A board game costs {c49}. Pip has {c9} and saves {c8} a week. How many weeks of waiting is that?\n{c49} − {c9} = {c40} still to find, at {c8} a week: 5 weeks. That is the cost of waiting — in weeks.","route":"#/atlas/x-ch8","cta":"Open the lesson","maths":"M9","source":"Chapter 6 · Borrowing · Show me how","id":"f-genhow-owe-6-1200","bands":["sprout","builder"],"grp":"card:x-ch8"},"f-game-cc-how":{"kind":"gamehow","src":"game:cc#how","level":6,"topics":["game","game:cc","ch:c6"],"gate":{"chapter":"c6"},"title":"Compound Climb","body":"Hold to let your money grow, let go to bank it. Grow too greedily and a crash can wipe it out.\nEvery five years, drag the marker to where a steady charge would take you.\nHold space, or press and hold. ↑ ↓ and Enter for the marker.","route":"#/play/cc","cta":"Go and play","source":"Play · keys hold space · ↑↓ ⏎ · opens with Chapter 6 · Borrowing","id":"f-game-cc-how","bands":["sprout","builder"],"maths":"M11","because":"From Compound Climb","grp":"game:cc"},"f-ggoal-cc-estimate":{"kind":"gamegoal","src":"ggoal:cc#estimate","level":6,"topics":["game:cc","ch:c6"],"gate":{"chapter":"c6"},"title":"Compound Climb","body":"Every estimate inside the steady band","route":"#/play/cc","cta":"Go and play","source":"From Compound Climb · a goal to choose","id":"f-ggoal-cc-estimate","bands":["sprout","builder"],"maths":"M11","because":"From Compound Climb","grp":"ggoal:cc"},"f-word-trust-score-use":{"kind":"worduse","src":"word:Trust score#use","level":6,"topics":["word","word:Trust score","ch:c6"],"title":"Trust score","route":"#/words/Trust%20score","cta":"Money Words","source":"Money Words · first used in Chapter 6 · Borrowing","id":"f-word-trust-score-use","bands":["sprout","builder"],"maths":"M1","because":"A money word first used in Chapter 6 · Borrowing","grp":"word:Trust score"}};
